/* ============================================================
   Desk Scene (Mossy) — auto-generated by build.py, do not edit.
   Client carrier: full CSS + inlined WebP images (desktop dsh-app://).
   源：~/.dsh/profiles/node_modules/@local/desk-scene/lib/*
   ============================================================ */
window.__ModuleLoader__.load({
  id: '@local/desk-scene-ui',
  factory() {
    const CSS = "/* ============================================================================\n   Desk Scene (Mossy) — Design Tokens（单一事实来源）\n   DeepSeek Harness Web UI 皮肤的设计令牌。\n\n   前缀：--dsk-  (desk)\n   分层：1 原色 Primitives → 2 语义 Semantic → 3 组件 Component → 4 布局 Layout\n   用法：组件样式（design.css）只引用 var(--dsk-*)；本文件是唯一的取值处。\n   适配层（映射到 DSH 的 --dsw-* 主题令牌）见 design.css §0。\n   ============================================================================ */\n\n:root {\n  /* ---- 1. Primitives：原始调色板 ---- */\n  /* 面板描边：与 tab 下划线同色的深橄榄绿 */\n  --dsk-raw-frame: #475E29;\n  /* 正文墨色（橄榄调的近黑） */\n  --dsk-raw-ink: #333824;\n  /* 软炭灰（按钮文字 / 未激活 tab / 次级正文） */\n  --dsk-raw-charcoal: #444638;\n  /* 三级文字（时间戳 / 提示） */\n  --dsk-raw-olive-mute: #5C5E46;\n  /* 深橄榄（品牌词 / 激活态 / 链接） */\n  --dsk-raw-olive-deep: #475E29;\n  /* 鼠尾草绿（主操作 / 选中行） */\n  --dsk-raw-sage: #A7B07B;\n  --dsk-raw-sage-hover: #94A065;\n  --dsk-raw-sage-light: #B9BD92;\n  /* 奶油（聊天气泡 / 代码表面） */\n  --dsk-raw-cream: #EFDC9C;\n  /* 浅奶油（代码块 / 卡片 / 弹层） */\n  --dsk-raw-cream-soft: #F4E8BE;\n  /* 沙色（输入卡片 / 面板纸底） */\n  --dsk-raw-sand: #DED3B3;\n  /* 白纸（备用） */\n  --dsk-raw-white: #FFFFFF;\n  --dsk-raw-white-hover: #FBF4E4;\n  /* 浅绿纸（次级按钮：新建会话） */\n  --dsk-raw-sage-paper: #F1F6E4;\n  --dsk-raw-sage-paper-hover: #E8F0D5;\n  /* 浅绿线（次级按钮描边） */\n  --dsk-raw-sage-line: #C6D4A4;\n  /* 金（旧：新建会话按钮） */\n  --dsk-raw-gold: #ECD7AF;\n  --dsk-raw-gold-hover: #E8CC9E;\n  /* 陶土（金按钮描边） */\n  --dsk-raw-terra: #E1A06A;\n  /* 行底色（默认会话行，垫在壁纸上保证可读） */\n  --dsk-raw-row-wash: rgba(255, 252, 240, 0.10);\n  /* 列表名字的荧光笔底色（项目名 / 当前会话）——奶油纸上要更深一档才看得见 */\n  --dsk-raw-highlight: #E9CE8A;\n  /* 悬浮底色（橄榄调极淡，全站统一的 hover） */\n  --dsk-raw-hover-wash: rgba(71, 94, 41, 0.10);\n\n  /* ---- 2. Semantic：语义角色 ---- */\n  --dsk-text-primary: var(--dsk-raw-ink);\n  --dsk-text-secondary: var(--dsk-raw-charcoal);\n  --dsk-text-tertiary: var(--dsk-raw-olive-mute);\n  --dsk-text-on-action: var(--dsk-raw-charcoal);\n  --dsk-text-brand: var(--dsk-raw-olive-deep);\n  --dsk-surface-bubble: var(--dsk-raw-cream);\n  --dsk-surface-input: var(--dsk-raw-sand);\n  --dsk-surface-row: var(--dsk-raw-row-wash);\n  --dsk-highlight-project: var(--dsk-raw-highlight);\n  --dsk-surface-hover: var(--dsk-raw-hover-wash);\n  --dsk-border-frame: var(--dsk-raw-frame);\n  --dsk-border-action: var(--dsk-raw-olive-deep);\n  --dsk-action-primary: var(--dsk-raw-sage);\n  --dsk-action-primary-hover: var(--dsk-raw-sage-hover);\n  --dsk-action-soft: var(--dsk-raw-sage-light);\n  --dsk-action-gold: var(--dsk-raw-gold);\n  --dsk-action-gold-hover: var(--dsk-raw-gold-hover);\n  --dsk-action-gold-border: var(--dsk-raw-terra);\n\n  /* ---- 3. Component：组件令牌 ---- */\n  /* ==== 3.1 按钮规范（全站统一：primary / secondary / soft / ghost） ==== */\n  --dsk-btn-radius: 10px;\n  --dsk-btn-font-weight: 500;\n  --dsk-btn-transition: background-color 140ms ease, box-shadow 140ms ease, border-color 140ms ease;\n\n  /* primary —— 绿色实心：发送 / 停止 / 页面主按钮 */\n  --dsk-btn-primary-bg: var(--dsk-raw-sage);\n  --dsk-btn-primary-bg-hover: var(--dsk-raw-sage-hover);\n  --dsk-btn-primary-fg: var(--dsk-raw-charcoal);\n  --dsk-btn-primary-border: 1px solid rgba(71, 94, 41, 0.22);\n  --dsk-btn-primary-shadow: 0 1px 2px rgba(45, 41, 36, 0.14);\n\n  /* secondary —— 浅绿纸片 + 浅绿描边 + 深绿字：新建会话 / 次级操作 */\n  --dsk-btn-secondary-bg: var(--dsk-raw-sage-paper);\n  --dsk-btn-secondary-bg-hover: var(--dsk-raw-sage-paper-hover);\n  --dsk-btn-secondary-fg: var(--dsk-raw-olive-deep);\n  --dsk-btn-secondary-border: 1px solid var(--dsk-raw-sage-line);\n  --dsk-btn-secondary-shadow: 0 1px 2px rgba(45, 41, 36, 0.08), 0 3px 8px rgba(45, 41, 36, 0.05);\n\n  /* soft —— 淡绿实底、无描边：附件 + / 卡内小按钮 */\n  --dsk-btn-soft-bg: var(--dsk-raw-sage-light);\n  --dsk-btn-soft-bg-hover: #ABB283;\n  --dsk-btn-soft-fg: var(--dsk-raw-charcoal);\n\n  /* ghost —— 纯文字：工具行下拉触发器 */\n  --dsk-btn-ghost-fg: var(--dsk-text-secondary);\n  --dsk-btn-ghost-fg-hover: var(--dsk-text-brand);\n\n  /* ---- 3.2 兼容别名（旧变量一律指向按钮规范，勿在新代码里直接改） ---- */\n  --dsk-btn-new-bg: var(--dsk-btn-secondary-bg);\n  --dsk-btn-new-hover: var(--dsk-btn-secondary-bg-hover);\n  --dsk-btn-new-border: var(--dsk-btn-secondary-border);\n  --dsk-btn-new-text: var(--dsk-btn-secondary-fg);\n  --dsk-btn-new-shadow: var(--dsk-btn-secondary-shadow);\n  --dsk-btn-send-bg: var(--dsk-btn-primary-bg);\n  --dsk-btn-send-hover: var(--dsk-btn-primary-bg-hover);\n  --dsk-btn-send-text: var(--dsk-btn-primary-fg);\n  --dsk-btn-attach-bg: var(--dsk-btn-soft-bg);\n  /* tabs（聊天 / 轨迹） */\n  --dsk-tab-font-size: 15px;\n  --dsk-tab-line-height: 20px;\n  --dsk-tab-text: var(--dsk-text-secondary);\n  --dsk-tab-active-text: var(--dsk-text-brand);\n  --dsk-tab-underline-w: 3px;\n  --dsk-tab-underline-c: var(--dsk-text-brand);\n  /* 会话行 / 面板行 */\n  --dsk-row-bg: var(--dsk-surface-row);\n  --dsk-row-hover: var(--dsk-surface-hover);\n  --dsk-row-selected-bg: var(--dsk-action-primary);\n  --dsk-row-selected-border: var(--dsk-border-action);\n  /* 输入卡片 */\n  --dsk-input-bg: var(--dsk-surface-input);\n  --dsk-input-border: 2px solid var(--dsk-border-frame);\n  --dsk-input-radius: 20px;\n  --dsk-shadow-card: 0 10px 26px rgba(45, 41, 36, 0.13);\n  /* 品牌词 */\n  --dsk-brand-text: var(--dsk-text-brand);\n  /* 分隔线（橄榄调） */\n  --dsk-hairline: rgba(71, 94, 41, 0.38);\n\n  /* ---- 4. Layout：布局令牌 ---- */\n  --dsk-screen-margin: 16px;      /* 屏幕边距 */\n  --dsk-panel-gap: 8px;           /* 面板间距 */\n  --dsk-panel-pad: 10px;          /* 面板内边距 */\n  --dsk-panel-radius: 20px;       /* 面板圆角 */\n  --dsk-panel-border-w: 2px;      /* 面板边框宽（细线，和 tab 下划线同色） */\n\n  /* ---- 5. Layers：层级 ---- */\n  --dsk-z-stage: 20;              /* 灯 / 架子 / 垂吊植物（压在面板边框上，文字之下） */\n  --dsk-z-sidebar: 30;            /* 侧边栏内容（植物在其后） */\n  --dsk-z-lines: 35;\n  --dsk-z-pets: 40;               /* 猫 / 椅子 / 西高地 / 抽屉（浮在内容之上） */\n}\n\n/* ---- 6. Adapter 映射表（落地在 design.css §0，这里仅作文档）\n   浅色（设计态）：--dsw-* 全面换成大地色系；\n   深色：保留 DSH 原值，仅隐藏壁纸与桌搭，保证暗色可读。\n   详见 design.css 的 body:not([data-ds-dark-theme]) 块。\n   ---- */\n\n/* ============================================================================\n   Desk Scene (Mossy) — 组件样式（消费 tokens.css 里的 --dsk-* 令牌）\n   规则：颜色/字号/间距一律引用令牌；几何与挂载位置可直写。\n\n   结构（与 design.js 的运行时标记对应）：\n     [data-dsh-frame]           应用 AppFrame（整窗网格）\n     [data-dsh-col=\"sidebar\"]   左栏（侧边栏面板）\n     [data-dsh-col=\"center\"]    中栏（对话 / 全局页面面板）\n     [data-dsh-col=\"rightbar\"]  右栏（检查器面板）\n     [data-dsh-main]            中栏主面板（全局页面时带 data-global-panel）\n     [data-dsh-sidebar]         侧边栏内容根（植物垫底）\n     [data-composer-card]       输入卡片（原生 data 属性，宠物锚点）\n     body[data-dsh-global=\"1\"]  当前是全局页面（插件 / 自动化任务 …）\n     body[data-dsh-modal=\"1\"]   当前有模态层（设置 …）\n   除这些标记外，组件选择器一律用「类名片段」匹配（如 [class*=\"_sessionRow\"]），\n   不依赖构建哈希前缀，应用升级后哈希变化也能命中。\n   ============================================================================ */\n\n/* ==========================================================================\n   §0 主题令牌适配层：把 DSH 的 --dsw-* 语义令牌换成大地色系（浅色）\n   深色保留 DSH 原值（只在 §10 隐藏壁纸与桌搭）。\n   ========================================================================== */\nbody:not([data-ds-dark-theme]) {\n  /* 表面 */\n  --dsw-alias-bg-base: transparent !important;\n  --dsw-alias-bg-layer-1: rgba(250, 245, 228, 0.78) !important;\n  --dsw-alias-bg-layer-2: #f6edd0 !important;\n  --dsw-alias-bg-layer-3: #efdc9c !important;\n  --dsw-alias-bg-overlay: #f6edd0 !important;\n  --dsw-alias-bg-mask-1: rgba(45, 41, 36, 0.28) !important;\n  --dsw-specific-sidebar-fill: transparent !important;\n  --dsw-specific-menu: rgba(247, 240, 220, 0.94) !important;\n  --dsw-alias-menu-group-header-fill: rgba(240, 231, 205, 0.94) !important;\n  --dsw-specific-menu-fill: rgba(247, 240, 220, 0.94) !important;\n  --dsw-alias-toast-bg: #333824 !important;\n  --dsw-alias-toast-label: #f7f0d8 !important;\n  --dsw-alias-tooltip-bg: #444638 !important;\n  --dsw-alias-tooltip-key-bg: rgba(247, 240, 216, 0.16) !important;\n  --dsw-menu-surface-fill: rgba(247, 240, 220, 0.94) !important;\n  --dsw-menu-backdrop-filter: blur(20px) saturate(120%) !important;\n  --dsw-alias-turn-trigger-bg: #f3e6b8 !important;\n  --dsw-alias-turn-trigger-bg-hover: #eadfaf !important;\n\n  /* 文字 */\n  --dsw-alias-label-primary: #333824 !important;\n  --dsw-alias-label-primary-bluish: #333824 !important;\n  --dsw-alias-label-primary-dimmed: #2d2924 !important;\n  --dsw-alias-label-secondary: #444638 !important;\n  --dsw-alias-label-tertiary: #5c5e46 !important;\n  --dsw-alias-label-caption: #6e7052 !important;\n  --dsw-alias-label-dimmed: #8c8e72 !important;\n  --dsw-alias-label-primary-foreground: #2d2924 !important;\n  --dsw-alias-label-primary-inverted: #f7f0d8 !important;\n  --dsw-alias-menu-icon: #444638 !important;\n  --dsw-alias-link: #475e29 !important;\n  --dsw-alias-brand-text: #475e29 !important;\n  --dsw-alias-brand-primary: #475e29 !important;\n  --dsw-alias-state-business-primary: #475e29 !important;\n  --dsw-alias-state-business-tertiary: #dde0c2 !important;\n  --dsw-alias-state-warn-label: #94551f !important;\n\n  /* 描边 */\n  --dsw-alias-border-l1: rgba(45, 41, 36, 0.12) !important;\n  --dsw-alias-border-l2: rgba(45, 41, 36, 0.20) !important;\n  --dsw-alias-border-l3: rgba(45, 41, 36, 0.28) !important;\n  --dsw-alias-border-l4: rgba(45, 41, 36, 0.38) !important;\n  --dsw-alias-border-inverted: rgba(247, 240, 216, 0.24) !important;\n  --dsw-alias-border-inverted2: rgba(247, 240, 216, 0.38) !important;\n\n  /* 交互底色 */\n  --dsw-alias-interactive-bg-hover: rgba(71, 94, 41, 0.10) !important;\n  --dsw-alias-interactive-bg-active: rgba(71, 94, 41, 0.16) !important;\n  --dsw-alias-interactive-bg-hover-solid: #e3e0c2 !important;\n  --dsw-alias-interactive-bg-hover-accent: rgba(71, 94, 41, 0.20) !important;\n\n  /* 按钮 */\n  --dsw-alias-button-primary-fill: #a7b07b !important;\n  --dsw-alias-button-primary-hover: #94a065 !important;\n  --dsw-alias-button-primary-dimmed: #c2c8a6 !important;\n  --dsw-alias-button-elevated-fill: #ecd7af !important;\n  --dsw-alias-button-floating-fill: #fbf6e4 !important;\n  --dsw-alias-button-floating-hover: #f3ead0 !important;\n  --dsw-alias-button-contrast-fill: #444638 !important;\n  --dsw-alias-button-ghost-active-fill: #e0dcbe !important;\n  --dsw-alias-button-ghost-active-border: #475e29 !important;\n  --dsw-alias-button-ghost-active-hover: #d5d2b0 !important;\n  --dsw-alias-button-info-fill: #a7b07b !important;\n  --dsw-alias-button-info-hover: #94a065 !important;\n\n  /* 输入 / 气泡 / Markdown */\n  --dsw-specific-input-major: #ded3b3 !important;\n  --dsw-specific-selector: #b9bd92 !important;\n  --dsw-specific-sidebar-nav-item-active: #b9bd92 !important;\n  --dsw-specific-sidebar-nav-item-active-accent: #475e29 !important;\n  --dsw-specific-bubble: #efdc9c !important;\n  --dsw-specific-bubble-highlight: #efdc9c !important;\n  --dsw-alias-markdown-code-block: #f3e6b8 !important;\n  --dsw-alias-markdown-code-block-banner: #e8dcae !important;\n  --dsw-alias-markdown-inline-code: #efe3b6 !important;\n  --dsw-alias-markdown-citation: #efdc9c !important;\n  --dsw-alias-markdown-tag: #e7ddb4 !important;\n  --dsw-alias-markdown-placeholder: #6e7052 !important;\n  --dsw-alias-markdown-code-segment-selected: #fbf4dc !important;\n  --dsw-alias-markdown-code-segment-unselected: #e8ddb2 !important;\n  --dsw-alias-code-diff-added: rgba(71, 94, 41, 0.12) !important;\n  --dsw-alias-code-diff-deleted: rgba(178, 74, 47, 0.12) !important;\n\n  /* 设置卡片 */\n  --dsw-alias-settings-card-fill: rgba(250, 245, 228, 0.55) !important;\n  --dsw-alias-settings-card-stroke: rgba(45, 41, 36, 0.20) !important;\n\n  /* 滚动条 / 阴影 / 圆角（全局统一到桌面绘本的圆润度） */\n  --dsw-alias-scrollbar-bg-l1: rgba(71, 94, 41, 0.30) !important;\n  --dsw-alias-scrollbar-bg-l2: rgba(71, 94, 41, 0.30) !important;\n  --dsw-alias-scrollbar-hover-l1: rgba(71, 94, 41, 0.50) !important;\n  --dsw-alias-scrollbar-hover-l2: rgba(71, 94, 41, 0.50) !important;\n  --dsw-alias-switch-thumb: #fbf6e4 !important;\n  --dsw-elevation-stroke-color: rgba(45, 41, 36, 0.22) !important;\n\n  --dsw-radius-panel: 20px;\n  --dsw-radius-xl: 18px;\n  --dsw-radius-lg: 12px;\n  --dsw-radius-md: 10px;\n  --dsw-radius-sm: 8px;\n}\n\n/* ==========================================================================\n   §1 壁纸 + 面板外框（16px 屏幕边距 / 8px 间距 / 3px 墨线 / 20px 圆角 / 10px 内边距）\n   应用把 grid 列宽按「整窗宽度」算，所以不用 frame padding（会溢出右侧），\n   而是给三列各加 margin —— 轨道宽度不变，内容盒向内收，右缘不会溢出。\n   ========================================================================== */\nhtml,\nbody {\n  background-color: #cfcdb0 !important;\n}\nbody:not([data-ds-dark-theme]) {\n  background-image: url('data:image/webp;base64,') !important;\n  background-size: cover !important;\n  background-position: center top !important;\n  background-repeat: no-repeat !important;\n  background-attachment: fixed !important;\n}\nbody[data-ds-dark-theme] {\n  background-image: none !important;\n  background-color: #151517 !important;\n}\n\n[data-dsh-frame] {\n  background: transparent !important;\n  padding: 0 !important;\n  overflow: clip !important;\n}\n\n[data-dsh-col] {\n  background: transparent !important;\n  box-sizing: border-box !important;\n}\n[data-dsh-col=\"sidebar\"] {\n  margin: var(--dsk-screen-margin) 0 var(--dsk-screen-margin) var(--dsk-screen-margin) !important;\n  border: var(--dsk-panel-border-w) solid var(--dsk-border-frame) !important;\n  border-radius: var(--dsk-panel-radius) !important;\n  padding: var(--dsk-panel-pad) !important;\n  box-shadow: inset 0 0 0 var(--dsk-panel-border-w) var(--dsk-border-frame) !important;\n  overflow: visible !important;\n}\n[data-dsh-col=\"center\"] {\n  margin: var(--dsk-screen-margin) var(--dsk-screen-margin) var(--dsk-screen-margin) var(--dsk-panel-gap) !important;\n  border: var(--dsk-panel-border-w) solid var(--dsk-border-frame) !important;\n  border-radius: var(--dsk-panel-radius) !important;\n  padding: var(--dsk-panel-pad) !important;\n  box-shadow: inset 0 0 0 var(--dsk-panel-border-w) var(--dsk-border-frame) !important;\n}\n[data-dsh-col=\"rightbar\"] {\n  margin: var(--dsk-screen-margin) var(--dsk-screen-margin) var(--dsk-screen-margin) 0 !important;\n  border: var(--dsk-panel-border-w) solid var(--dsk-border-frame) !important;\n  border-radius: var(--dsk-panel-radius) !important;\n  padding: var(--dsk-panel-pad) !important;\n  box-shadow: inset 0 0 0 var(--dsk-panel-border-w) var(--dsk-border-frame) !important;\n}\n[data-dsh-frame][data-rightbar-collapsed] [data-dsh-col=\"center\"] {\n  margin-right: var(--dsk-screen-margin) !important;\n}\n/* rail（收起侧边栏）：窄条里清掉内边距与粗边框，保证展开按钮不被裁掉 */\n[data-dsh-frame][data-sidebar-collapsed] [data-dsh-col=\"sidebar\"] {\n  margin: 8px 0 8px 8px !important;\n  padding: 0 !important;\n  border-width: 2px !important;\n  border-radius: 14px !important;\n  box-shadow: inset 0 0 0 2px var(--dsk-border-frame) !important;\n}\n[data-dsh-frame][data-sidebar-collapsed] [data-dsh-sidebar] {\n  padding: 2px 0 !important;\n}\n/* 抽屉式侧栏（窄窗口）：不再需要左右外边距的挤压感 */\n[data-dsh-frame][data-sidebar-drawer] [data-dsh-col=\"sidebar\"] {\n  margin: var(--dsk-screen-margin) !important;\n}\n\n/* 右侧 dock 面板（浏览器 / 终端 / 文件…）：\n   应用给面板写的是 track 宽度（inline `--dsh-sidebar-width`），而本主题给右栏加了\n   margin / border / padding，面板又是 right:0 + absolute 定位 —— 结果面板宽度大于栏的\n   padding box，往左溢出，把右栏的左描边盖住（右侧因为右对齐所以没事）。\n   这里把面板限制在右栏的内容区里：原生 webview 也跟着退进描边以内。 */\n[data-dsh-col=\"rightbar\"] [style*=\"--dsh-sidebar-width\"]:not([data-sidebar-right-panel=\"fullscreen\"]) {\n  left: var(--dsk-panel-pad) !important;\n  right: var(--dsk-panel-pad) !important;\n  top: var(--dsk-panel-pad) !important;\n  bottom: var(--dsk-panel-pad) !important;\n  width: auto !important;\n  border-radius: 14px !important;\n  overflow: clip !important;\n}\n\n/* 面板内容裁切：中栏 / 右栏的内容（文件预览、tab 条等）不许越过圆角边框；\n   左栏保留 overflow visible，植物可以探出面板边缘。 */\n[data-dsh-col=\"sidebar\"],\n[data-dsh-col=\"center\"],\n[data-dsh-col=\"rightbar\"] {\n  isolation: isolate;\n}\n[data-dsh-col=\"center\"],\n[data-dsh-col=\"rightbar\"] {\n  overflow: hidden !important;\n}\n\n/* ==========================================================================\n   §2 基础文字 / 全局表面\n   ========================================================================== */\nbody:not([data-ds-dark-theme]) {\n  color: var(--dsk-text-primary);\n}\n[data-dsh-main] {\n  background: transparent !important;\n}\n[data-dsh-main] ::selection {\n  background: rgba(71, 94, 41, 0.24);\n}\n\n/* 全局页面的滚动区给一点纸感（壁纸直接透出，只留极淡的暖白） */\nbody:not([data-ds-dark-theme]) [data-dsh-main][data-global-panel] {\n  background: transparent !important;\n}\n\n/* ==========================================================================\n   §3 侧边栏\n   ========================================================================== */\n[data-dsh-sidebar] {\n  position: relative;\n  z-index: var(--dsk-z-sidebar);\n  background: transparent !important;\n  width: 100% !important;\n  box-sizing: border-box !important;\n}\n[data-dsh-sidebar] [class*=\"_brand\"] {\n  color: var(--dsk-brand-text) !important;\n}\n[data-dsh-sidebar] [class*=\"_brandName\"] {\n  color: var(--dsk-brand-text) !important;\n  letter-spacing: 0.02em;\n}\n/* 新建会话：金色便签（只作用于按钮本体，避免内部 LabelMask/Content 也被描边） */\n[data-dsh-sidebar] button[class*=\"_newSession\"] {\n  background: var(--dsk-btn-secondary-bg) !important;\n  border: var(--dsk-btn-secondary-border) !important;\n  border-radius: var(--dsk-btn-radius) !important;\n  color: var(--dsk-btn-secondary-fg) !important;\n  font-weight: var(--dsk-btn-font-weight) !important;\n  box-shadow: var(--dsk-btn-secondary-shadow) !important;\n  transition: var(--dsk-btn-transition) !important;\n}\n[data-dsh-sidebar] button[class*=\"_newSession\"]:hover {\n  background: var(--dsk-btn-secondary-bg-hover) !important;\n  border-color: var(--dsk-raw-sage) !important;\n  box-shadow: 0 2px 4px rgba(45, 41, 36, 0.10), 0 6px 14px rgba(45, 41, 36, 0.07) !important;\n}\n[data-dsh-sidebar] button[class*=\"_newSession\"] > * {\n  color: var(--dsk-btn-secondary-fg) !important;\n}\n/* 顶部面板行（Plugins / Automation tasks / More） */\n[data-dsh-sidebar] [class*=\"_panelRow\"] {\n  border-radius: 10px !important;\n  color: var(--dsk-text-primary) !important;\n  transition: background-color 0.12s ease;\n}\n[data-dsh-sidebar] [class*=\"_panelRow\"]:hover {\n  background: var(--dsk-row-hover) !important;\n}\n[data-dsh-sidebar] [class*=\"_panelRow\"][class*=\"_panelActive\"] {\n  background: var(--dsk-row-selected-bg) !important;\n  color: var(--dsk-text-on-action) !important;\n}\n[data-dsh-sidebar] [class*=\"_panelGlyph\"] {\n  color: var(--dsk-text-brand) !important;\n}\n/* Workspaces 区 */\n[data-dsh-sidebar] [class*=\"_sectionLabel\"] {\n  color: var(--dsk-text-primary) !important;\n  font-weight: 500 !important;\n}\n/* 列表行：不铺整行底色（壁纸直接透出），hover 才给极淡的橄榄底 */\n[data-dsh-sidebar] [class*=\"_projectRow\"],\n[data-dsh-sidebar] [class*=\"_sessionRow\"] {\n  background: transparent !important;\n  box-shadow: none !important;\n  border-radius: 10px !important;\n  box-sizing: border-box !important;\n}\n[data-dsh-sidebar] [class*=\"_projectRow\"]:hover,\n[data-dsh-sidebar] [class*=\"_sessionRow\"]:hover {\n  background: var(--dsk-row-hover) !important;\n}\n/* 项目（工作区）行：整行高亮（蜂蜜色纸底），名字不再单独画荧光笔 */\n[data-dsh-sidebar] [class*=\"_projectRow\"] {\n  background: rgba(233, 206, 138, 0.34) !important;\n  border-radius: 10px !important;\n}\n[data-dsh-sidebar] [class*=\"_projectRow\"]:hover {\n  background: rgba(233, 206, 138, 0.52) !important;\n}\n[data-dsh-sidebar] [class*=\"_projectRow\"] [class*=\"_projectText\"] > [class*=\"_title\"] {\n  flex: 0 1 auto !important;\n  width: auto !important;\n  max-width: 100% !important;\n  font-weight: 600 !important;\n  color: var(--dsk-text-primary) !important;\n  background-image: none !important;\n}\n/* 会话行：默认透明，文字保持原有左右布局 */\n[data-dsh-sidebar] [class*=\"_sessionRow\"] [class*=\"_title\"] {\n  flex: 0 1 auto !important;\n  margin-right: auto !important;\n  color: var(--dsk-text-primary) !important;\n  background-image: none !important;\n}\n/* 当前会话：整行高亮（鼠尾草绿纸底 + 橄榄细边） */\n[data-dsh-sidebar] [class*=\"_sessionRow\"][class*=\"_selected\"] {\n  background: var(--dsk-row-selected-bg) !important;\n  box-shadow: none !important;\n}\n[data-dsh-sidebar] [class*=\"_sessionRow\"][class*=\"_selected\"] [class*=\"_title\"] {\n  font-weight: 600 !important;\n  color: var(--dsk-text-primary) !important;\n  background-image: none !important;\n}\n[data-dsh-sidebar] [class*=\"_sessionRow\"][class*=\"_selected\"] [class*=\"_time\"],\n[data-dsh-sidebar] [class*=\"_sessionRow\"][class*=\"_selected\"] [class*=\"_meta\"] {\n  color: var(--dsk-text-tertiary) !important;\n}\n[data-dsh-sidebar] [class*=\"_time\"],\n[data-dsh-sidebar] [class*=\"_meta\"],\n[data-dsh-sidebar] [class*=\"_rowResting\"] {\n  color: var(--dsk-text-tertiary) !important;\n}\n[data-dsh-sidebar] [class*=\"_folderActive\"] {\n  color: var(--dsk-text-brand) !important;\n}\n/* 底部账号行 */\n[data-dsh-sidebar] [class*=\"_footArea\"] [class*=\"_trigger\"],\n[data-dsh-sidebar] [class*=\"_trigger\"] {\n  color: var(--dsk-text-primary) !important;\n}\n/* 侧边栏图标按钮 hover */\n[data-dsh-sidebar] button:hover {\n  color: var(--dsk-text-brand);\n}\n\n/* ==========================================================================\n   §4 会话页头 / Tabs\n   ========================================================================== */\n[data-dsh-main]:not([data-global-panel]) header[data-window-drag=\"true\"] {\n  border-bottom: 1px solid var(--dsk-hairline) !important;\n}\n[data-dsh-main] [role=\"tab\"] {\n  position: relative;\n  color: var(--dsk-tab-text) !important;\n  font-size: var(--dsk-tab-font-size) !important;\n  line-height: var(--dsk-tab-line-height) !important;\n}\n[data-dsh-main] [role=\"tab\"][aria-selected=\"true\"] {\n  color: var(--dsk-tab-active-text) !important;\n  font-weight: 600 !important;\n}\n[data-dsh-main] [role=\"tab\"][aria-selected=\"true\"]::after {\n  content: '';\n  position: absolute;\n  left: 10px;\n  right: 10px;\n  bottom: 0;\n  height: var(--dsk-tab-underline-w);\n  border-radius: 2px;\n  background: var(--dsk-tab-underline-c);\n}\n/* 页头标题 */\n[data-dsh-main] [class*=\"_crumbs\"] [class*=\"_crumbCurrent\"] {\n  color: var(--dsk-text-primary) !important;\n  font-weight: 600 !important;\n}\n/* 页头图标按钮：让 ghost 按钮的底在壁纸上也看得见 */\n[data-dsh-main] button[class*=\"_ghost\"]:hover {\n  background: var(--dsk-surface-hover) !important;\n}\n/* 页头右上角的「在 Finder 中打开」分体按钮：做成和会话日志同款的小药丸 */\n[data-dsh-main]:not([data-global-panel]) header [class*=\"_split\"] {\n  background: var(--dsk-action-soft) !important;\n  border: 1px solid rgba(45, 41, 36, 0.34) !important;\n  border-radius: 9px !important;\n  overflow: hidden;\n}\n[data-dsh-main]:not([data-global-panel]) header [class*=\"_split\"] button {\n  background: transparent !important;\n}\n\n/* ==========================================================================\n   §5 对话内容\n   ========================================================================== */\n/* 用户气泡：奶油底 + 墨字（令牌已接管底色，这里补圆角与描边细节） */\n[data-dsh-main] [class*=\"_bubble\"] {\n  border-radius: 18px !important;\n}\n/* 代码 / 引用等表面统一暖白 */\n[data-dsh-main] pre,\n[data-dsh-main] code {\n  border-color: rgba(45, 41, 36, 0.18) !important;\n}\n/* 行内代码给一点描边，压在壁纸上更清楚 */\n[data-dsh-main] :not(pre) > code {\n  border: 1px solid rgba(45, 41, 36, 0.16) !important;\n  border-radius: 6px !important;\n  padding: 1px 4px !important;\n}\n/* 计划 / To-dos 浮条 */\n[data-dsh-main] [class*=\"_todo\"],\n[data-dsh-main] [class*=\"_plan\"] {\n  border-radius: 14px !important;\n}\n/* 输入框上方的统计栏 */\n[data-dsh-main] [class*=\"_composerDock\"],\n[data-dsh-main] [class*=\"_stats\"] {\n  color: var(--dsk-text-tertiary) !important;\n}\n\n/* 聊天列宽：绘本式窄栏（780 宽的输入卡 ≈ 上一版主题的手感）\n   用 min() 兜底：窗口太窄时跟随应用给的真实列宽收缩，不会溢出面板。 */\n[data-dsh-chat-body] {\n  --dsh-chat-user-width: min(748px, calc(var(--dsh-conversation-column-width, 820px) - 96px)) !important;\n}\n\n/* ==========================================================================\n   §6 输入卡片（Composer）\n   ========================================================================== */\n[data-composer-card] {\n  background: var(--dsk-surface-input) !important;\n  border: var(--dsk-input-border) !important;\n  border-radius: var(--dsk-input-radius) !important;\n  box-shadow: var(--dsk-shadow-card) !important;\n}\n/* 发送 / 停止按钮（primary） */\n[data-composer-card] [class*=\"_primary\"] {\n  background: var(--dsk-btn-primary-bg) !important;\n  color: var(--dsk-btn-primary-fg) !important;\n  box-shadow: var(--dsk-btn-primary-shadow) !important;\n  transition: var(--dsk-btn-transition) !important;\n}\n[data-composer-card] [class*=\"_primary\"]:hover:not(:disabled) {\n  background: var(--dsk-btn-primary-bg-hover) !important;\n}\n[data-composer-card] [class*=\"_primary\"] * {\n  color: var(--dsk-btn-primary-fg) !important;\n}\n/* 附件 +（soft） */\n[data-composer-card] [class*=\"_add\"] {\n  background: var(--dsk-btn-soft-bg) !important;\n  color: var(--dsk-btn-soft-fg) !important;\n  transition: var(--dsk-btn-transition) !important;\n}\n[data-composer-card] [class*=\"_add\"]:hover {\n  background: var(--dsk-btn-soft-bg-hover) !important;\n}\n/* 工具行里的下拉触发器（ghost） */\n[data-composer-card] [class*=\"_trigger\"] {\n  color: var(--dsk-btn-ghost-fg) !important;\n}\n[data-composer-card] [class*=\"_trigger\"]:hover {\n  color: var(--dsk-btn-ghost-fg-hover) !important;\n}\n/* 卡内 placeholder / 输入文字 */\n[data-composer-card] [class*=\"_placeholder\"] {\n  color: var(--dsk-text-tertiary) !important;\n}\n/* 输入卡外部保持干净：座位层不加任何灰底，沙色只留在输入卡内部 */\nbody[data-dsh-docked=\"1\"] [data-dsh-main] [class*=\"_composerSeat\"] {\n  background: transparent !important;\n}\n\n/* ==========================================================================\n   §7 全局页面（Plugins / Automation tasks / 市场 …）\n   ========================================================================== */\n/* 页面标题 / 说明 */\n[data-dsh-main][data-global-panel] [class*=\"_pageTitle\"] {\n  color: var(--dsk-text-primary) !important;\n  letter-spacing: 0.01em;\n}\n[data-dsh-main][data-global-panel] [class*=\"_pageIntro\"] {\n  color: var(--dsk-text-secondary) !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_groupTitle\"] {\n  color: var(--dsk-text-primary) !important;\n  font-weight: 600 !important;\n}\n/* 插件 / 任务卡片：纸片感 + hover */\n[data-dsh-main][data-global-panel] [class*=\"_card\"] {\n  border-radius: 16px !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_card\"]:hover {\n  background: rgba(255, 252, 240, 0.20) !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_cardIcon\"] {\n  background: rgba(255, 252, 240, 0.55) !important;\n  border-color: rgba(45, 41, 36, 0.24) !important;\n  border-radius: 14px !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_cardTitle\"] {\n  color: var(--dsk-text-primary) !important;\n  font-weight: 600 !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_cardDesc\"],\n[data-dsh-main][data-global-panel] [class*=\"_cardMeta\"] {\n  color: var(--dsk-text-secondary) !important;\n}\n/* 任务页筛选 tab -> 药丸 */\n[data-dsh-main][data-global-panel] [class*=\"_filterTab\"] {\n  border-radius: 999px !important;\n  color: var(--dsk-text-secondary) !important;\n  border: 1px solid transparent !important;\n  padding: 4px 12px !important;\n  min-height: 28px !important;\n  height: 28px !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_filterTab\"]:hover {\n  background: var(--dsk-surface-hover) !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_filterTab\"][class*=\"_filterTabActive\"] {\n  background: var(--dsk-action-primary) !important;\n  color: var(--dsk-text-on-action) !important;\n  border-color: var(--dsk-border-action) !important;\n}\n/* 主按钮（Add plugin / New）：鼠尾草绿 + 墨字 */\n[data-dsh-main][data-global-panel] [class*=\"_primary\"] {\n  color: var(--dsk-text-on-action) !important;\n}\n[data-dsh-main][data-global-panel] [class*=\"_primary\"] * {\n  color: var(--dsk-text-on-action) !important;\n}\n\n/* ==========================================================================\n   §8 弹层 / 菜单 / 设置\n   ========================================================================== */\n[role=\"dialog\"] {\n  color: var(--dsk-text-primary);\n}\n[role=\"dialog\"]:has([data-slot=\"settings.header\"]) {\n  border: var(--dsk-panel-border-w) solid var(--dsk-border-frame) !important;\n  box-shadow: var(--dsk-shadow-card) !important;\n}\n[class*=\"_material\"] {\n  border-radius: 14px;\n}\n[class*=\"_item_\"]:hover {\n  border-radius: 10px;\n}\n/* 设置面板（role=dialog 的大面板） */\n[role=\"dialog\"] [class*=\"_navCell\"] {\n  border-radius: 10px !important;\n  color: var(--dsk-text-primary) !important;\n}\n[role=\"dialog\"] [class*=\"_navCell\"][class*=\"_active\"] {\n  background: var(--dsk-action-primary) !important;\n  color: var(--dsk-text-on-action) !important;\n}\n[role=\"dialog\"] [class*=\"_navTitle\"] {\n  color: var(--dsk-text-brand) !important;\n  font-weight: 600 !important;\n}\n[role=\"dialog\"] [class*=\"_close\"]:hover {\n  background: var(--dsk-surface-hover) !important;\n}\n\n/* ==========================================================================\n   §9 装饰：壁上的桌搭（stage）+ 侧边栏植物 + 宠物\n   ========================================================================== */\n.dsh-deco-stage {\n  position: absolute;\n  inset: 0;\n  z-index: var(--dsk-z-stage);\n  pointer-events: none;\n  overflow: hidden;\n}\n.dsh-deco-shelf {\n  position: absolute;\n  top: 31px;\n  right: 57px;\n  width: 277px;\n  height: 66px;\n  pointer-events: none;\n  user-select: none;\n}\n.dsh-deco-vine {\n  position: absolute;\n  top: 85px;\n  right: 57px;\n  width: 278px;\n  height: 186px;\n  pointer-events: none;\n  user-select: none;\n}\n.dsh-deco-lamp {\n  position: absolute;\n  top: 2px;\n  right: 307px;\n  width: 502px;\n  height: 347px;\n  pointer-events: none;\n  user-select: none;\n  transition: left 0.35s ease, right 0.35s ease;\n}\n/* 侧边栏植物：垫在最底层（[data-dsh-sidebar] 是层叠上下文），\n   位置/尺寸由 design.js 动态算在「列表底部 ~ 账号行」的空白里，不压文字；\n   放不下时 body[data-dsh-tree=\"0\"] 直接隐藏。 */\n.dsh-deco-tree {\n  position: absolute;\n  left: -42px;\n  bottom: 140px;\n  width: 236px;\n  height: auto;\n  z-index: -1;\n  pointer-events: none;\n  user-select: none;\n  opacity: 0.97;\n}\nbody[data-dsh-tree=\"0\"] .dsh-deco-tree {\n  display: none !important;\n}\n/* 面板描边覆盖层：把三栏 stroke 再画一遍到内容之上（宠物层之下），\n   防止 iframe / 网页预览等内部内容画到边框上把墨线盖住。 */\n.dsh-frame-lines {\n  position: fixed;\n  inset: 0;\n  z-index: var(--dsk-z-lines);\n  pointer-events: none;\n  overflow: hidden;\n}\n.dsh-frame-line {\n  position: fixed;\n  box-sizing: border-box;\n  pointer-events: none;\n  display: none;\n}\n\n/* 宠物层：浮在面板边框之上 */\n.dsh-pets {\n  position: fixed;\n  inset: 0;\n  z-index: var(--dsk-z-pets);\n  pointer-events: none;\n  overflow: hidden;\n}\n.dsh-pets img {\n  position: absolute;\n  display: none;\n  pointer-events: none;\n  user-select: none;\n}\nbody[data-dsh-pets=\"1\"] .dsh-pets img {\n  display: block;\n}\n\n/* ---- 猫咪交互：睡猫可点（收起成小猫头）/ 收起态 32×32 猫头 / 提示气泡 ---- */\n.dsh-cat-btn {\n  position: absolute;\n  display: block;\n  background: none;\n  border: 0;\n  padding: 0;\n  margin: 0;\n  cursor: pointer;\n  pointer-events: auto;\n  line-height: 0;\n  -webkit-appearance: none;\n  appearance: none;\n  z-index: 15;\n}\n.dsh-cat-btn img {\n  position: absolute;\n  inset: 0;\n  display: block !important;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n}\n.dsh-cat-btn:focus-visible {\n  outline: 2px solid var(--dsk-border-frame, #475E29);\n  outline-offset: 3px;\n  border-radius: 12px;\n}\n.dsh-cathead-btn {\n  position: absolute;\n  width: 32px;\n  height: 22px;\n  padding: 0;\n  margin: 0;\n  background: none;\n  border: 0;\n  cursor: pointer;\n  pointer-events: auto;\n  line-height: 0;\n  -webkit-appearance: none;\n  appearance: none;\n  z-index: 16;\n}\n.dsh-cathead-btn img {\n  position: absolute;\n  inset: 0;\n  display: block !important;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  pointer-events: none;\n}\n.dsh-cathead-btn:focus-visible {\n  outline: 2px solid var(--dsk-border-frame, #475E29);\n  outline-offset: 2px;\n  border-radius: 8px;\n}\n.dsh-cat-ghost {\n  position: absolute;\n  display: block !important;\n  pointer-events: none;\n  user-select: none;\n  z-index: 14;\n}\nbody[data-dsh-cat=\"expanded\"] .dsh-cathead-btn,\nbody[data-dsh-cat=\"collapsed\"] .dsh-cat-btn {\n  display: none !important;\n}\nbody[data-dsh-pets=\"0\"] .dsh-cat-btn,\nbody[data-dsh-pets=\"0\"] .dsh-cathead-btn,\nbody[data-dsh-pets=\"0\"] .dsh-cat-tip {\n  display: none !important;\n}\n/* 提示气泡：纸片样式，悬停睡猫 / 猫头时出现 */\n.dsh-cat-tip {\n  position: fixed;\n  z-index: 80;\n  display: none;\n  max-width: 240px;\n  padding: 7px 10px;\n  border-radius: 10px;\n  border: 1.5px solid var(--dsk-border-frame, #475E29);\n  background: var(--dsk-raw-cream-soft, #f4e8be);\n  color: var(--dsk-text-primary, #333824);\n  font-size: 12px;\n  line-height: 17px;\n  box-shadow: 0 8px 20px rgba(45, 41, 36, 0.16);\n  pointer-events: none;\n  white-space: normal;\n}\nbody[data-dsh-cat-tip=\"1\"] .dsh-cat-tip {\n  display: block;\n}\n\n/* ==========================================================================\n   §10 页面模式：全局页面（隐藏桌搭、台灯居中）/ 模态层（全部隐藏）/ 深色\n   ========================================================================== */\n/* 全局页面：顶部桌搭不显示，只留台灯（design.js 把它居中到主面板）；\n   地板植物留在侧边栏底部，不挡任何按钮。 */\nbody[data-dsh-global=\"1\"] .dsh-deco-shelf,\nbody[data-dsh-global=\"1\"] .dsh-deco-vine,\nbody[data-dsh-global=\"1\"] .dsh-pets {\n  display: none !important;\n}\n/* 右侧检查器面板展开（三栏并排）：保留主题元素，\n   只收起顶部架子/垂吊（它们会压住右栏的 tab 条），台灯由 JS 居中到聊天栏 */\nbody[data-dsh-rightpanel=\"1\"] .dsh-deco-shelf,\nbody[data-dsh-rightpanel=\"1\"] .dsh-deco-vine {\n  display: none !important;\n}\n/* 模态层（设置 / 对话框）：整桌收起，避免压住按钮与内容 */\nbody[data-dsh-modal=\"1\"] .dsh-deco-stage,\nbody[data-dsh-modal=\"1\"] .dsh-deco-tree,\nbody[data-dsh-modal=\"1\"] .dsh-pets {\n  display: none !important;\n}\n/* 深色：隐藏壁纸与桌搭，只保留面板墨线与圆角 */\nbody[data-ds-dark-theme] .dsh-deco-stage,\nbody[data-ds-dark-theme] .dsh-deco-tree,\nbody[data-ds-dark-theme] .dsh-pets {\n  display: none !important;\n}\nbody[data-ds-dark-theme] [data-dsh-col] {\n  border-color: #8f8a6f !important;\n  box-shadow: inset 0 0 0 var(--dsk-panel-border-w) #8f8a6f !important;\n}\nbody[data-ds-dark-theme] [data-dsh-col=\"sidebar\"] {\n  box-shadow: inset 0 0 0 var(--dsk-panel-border-w) #8f8a6f !important;\n}\n\n\n/* 深色模式：本皮肤是「浅色绘本」主题，深色下只保留面板几何/墨线，\n   组件颜色交还给 DSH 自己的深色令牌，避免浅色底压在深色文字上。 */\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_projectRow\"],\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_sessionRow\"] {\n  background: transparent !important;\n  box-shadow: none !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_projectRow\"]:hover,\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_sessionRow\"]:hover {\n  background: rgba(255, 255, 255, 0.05) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_projectRow\"] {\n  background: rgba(167, 176, 123, 0.22) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_projectRow\"]:hover {\n  background: rgba(167, 176, 123, 0.32) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_projectRow\"] [class*=\"_projectText\"] > [class*=\"_title\"] {\n  color: #ece9d8 !important;\n  background-image: none !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_sessionRow\"][class*=\"_selected\"] {\n  background: rgba(167, 176, 123, 0.35) !important;\n  box-shadow: none !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_sessionRow\"][class*=\"_selected\"] [class*=\"_title\"] {\n  color: #ece9d8 !important;\n  background-image: none !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_panelRow\"][class*=\"_panelActive\"] {\n  background: rgba(167, 176, 123, 0.35) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] button[class*=\"_newSession\"] {\n  background: #2f3a26 !important;\n  border-color: #55683f !important;\n  color: #d9e4c2 !important;\n}\nbody[data-ds-dark-theme] [data-dsh-sidebar] button[class*=\"_newSession\"] > *,\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_brand\"],\nbody[data-ds-dark-theme] [data-dsh-sidebar] [class*=\"_brandName\"] {\n  color: #ece9d8 !important;\n}\nbody[data-ds-dark-theme] [data-composer-card] {\n  background: #26262a !important;\n  border-color: #8f8a6f !important;\n  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.4) !important;\n}\nbody[data-ds-dark-theme] [data-composer-card] [class*=\"_primary\"] {\n  background: #5b6b3c !important;\n  color: #f2f0e0 !important;\n}\nbody[data-ds-dark-theme] [data-composer-card] [class*=\"_add\"] {\n  background: #3a3b34 !important;\n  color: #ece9d8 !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main]:not([data-global-panel]) header[data-window-drag=\"true\"] {\n  border-bottom-color: rgba(220, 218, 190, 0.22) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main]:not([data-global-panel]) header [class*=\"_split\"] {\n  background: #33342a !important;\n  border-color: #6f6a52 !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main] [role=\"tab\"][aria-selected=\"true\"] {\n  color: #c9cba6 !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main] [role=\"tab\"][aria-selected=\"true\"]::after {\n  background: #c9cba6 !important;\n}\nbody[data-dsh-main][data-global-panel] [class*=\"_filterTab\"][class*=\"_filterTabActive\"] {\n  background: #a7b07b !important;\n  color: #2d2924 !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main][data-global-panel] [class*=\"_card\"]:hover {\n  background: rgba(255, 255, 255, 0.04) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main][data-global-panel] [class*=\"_cardIcon\"] {\n  background: rgba(255, 255, 255, 0.05) !important;\n  border-color: rgba(255, 255, 255, 0.14) !important;\n}\nbody[data-ds-dark-theme] [role=\"dialog\"] [class*=\"_navCell\"][class*=\"_active\"] {\n  background: rgba(167, 176, 123, 0.35) !important;\n  color: #ece9d8 !important;\n}\nbody[data-ds-dark-theme] [role=\"dialog\"] [class*=\"_navTitle\"] {\n  color: #c9cba6 !important;\n}\nbody[data-ds-dark-theme][data-dsh-docked=\"1\"] [data-dsh-main] [class*=\"_composerSeat\"] {\n  background: linear-gradient(180deg, rgba(21, 21, 23, 0) 0px, rgba(21, 21, 23, 0.85) 70px, #151517 100%) !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main] [class*=\"_bubble\"] {\n  border-radius: 18px !important;\n}\nbody[data-ds-dark-theme] [data-dsh-main] :not(pre) > code {\n  border-color: rgba(255, 255, 255, 0.16) !important;\n}\nbody[data-ds-dark-theme] .dsh-deco-stage,\nbody[data-ds-dark-theme] .dsh-deco-tree,\nbody[data-ds-dark-theme] .dsh-pets {\n  display: none !important;\n}\n\n/* ==========================================================================\n   §11 响应式 / 无障碍\n   ========================================================================== */\n@media (max-width: 900px) {\n  .dsh-deco-shelf,\n  .dsh-deco-vine {\n    display: none;\n  }\n}\n@media (prefers-reduced-motion: reduce) {\n  .dsh-deco-lamp {\n    transition: none;\n  }\n}\n\n/* Keep lamp and independently sized light anchored during layout changes. */\n.dsh-deco-stage .dsh-deco-lamp { transition: none; }\n.dsh-deco-stage .dsh-lamp-beam,\n.dsh-deco-stage .dsh-lamp-cutout {\n  display: none;\n  pointer-events: none;\n}\n.dsh-deco-stage .dsh-lamp-beam {\n  background: var(--dsh-beam-soft) center / 100% 100% no-repeat;\n  transform-origin: 72.709% 14.697%; /* 365, 51 */\n  transform: scale(var(--dsh-beam-scale, 1));\n  transition: none; /* Position follows the live shade anchor instead. */\n}\n.dsh-deco-stage .dsh-lamp-beam[data-mode=\"white\"],\n.dsh-deco-stage .dsh-lamp-beam[data-mode=\"rainbow\"] {\n  -webkit-mask: var(--dsh-beam-soft) center / 100% 100% no-repeat;\n  mask: var(--dsh-beam-soft) center / 100% 100% no-repeat;\n}\n.dsh-deco-stage .dsh-lamp-beam[data-mode=\"white\"] {\n  background: rgba(255, 255, 255, .85);\n}\n.dsh-deco-stage .dsh-lamp-beam[data-mode=\"rainbow\"] {\n  /* The original image is mostly left of the bulb, so the fan needs its own\n     wider canvas. Its center and scaling origin remain fixed at the opening. */\n  -webkit-mask: none;\n  mask: none;\n  background: none;\n  transform-origin: 72.709% 16.138%; /* lampshade opening: 365, 56 */\n}\n.dsh-deco-stage .dsh-lamp-beam[data-mode=\"rainbow\"]::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: calc(72.709% - 75%);\n  width: 150%;\n  height: 100%;\n  pointer-events: none;\n  -webkit-mask: var(--dsh-rainbow-mask) center / 100% 100% no-repeat;\n  mask: var(--dsh-rainbow-mask) center / 100% 100% no-repeat;\n  background: conic-gradient(from 0deg at 50% 16.138%,\n    #f0b6b6 0deg 125deg, #f0d68e 145deg, #acd4bb 165deg,\n    #a7bdef 185deg, #c5a8e9 205deg, #eeb5c3 225deg, #eeb5c3 360deg);\n}\n\n.dsh-light-ui {\n  position: fixed;\n  z-index: 36;\n  font-family: inherit;\n  font-size: 13px;\n  font-weight: 500;\n  line-height: 1.25;\n  color: var(--dsk-text-primary, #333824);\n}\n/* Reusable outline button: use the same ink as the panel stroke. */\n.dsh-btn-outline {\n  border: 1px solid var(--dsk-border-frame, #475e29);\n  background: transparent;\n  color: var(--dsk-border-frame, #475e29);\n}\n.dsh-btn-outline:hover { background: rgba(71, 94, 41, .08); }\n.dsh-btn-outline:focus-visible {\n  outline: 2px solid var(--dsk-border-frame, #475e29);\n  outline-offset: 2px;\n}\n.dsh-light-trigger {\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  width: max-content;\n  height: 32px;\n  padding: 0 8px;\n  white-space: nowrap;\n  border-radius: var(--dsk-btn-radius, 10px);\n  font-family: inherit;\n  font-size: 13px;\n  font-weight: 500;\n  line-height: 1.2;\n  cursor: pointer;\n}\n.dsh-light-compact .dsh-light-trigger > span { display: none; }\n.dsh-light-icon { flex: none; width: 19px; height: 19px; color: var(--dsk-text-brand, #475e29); }\n.dsh-light-icon-glow { fill: #edc771; opacity: .7; }\n.dsh-light-ui[data-mode=\"white\"] .dsh-light-icon-glow { fill: #fff; }\n.dsh-light-ui[data-mode=\"rainbow\"] .dsh-light-icon-glow { fill: url(#dsh-light-rainbow); }\n.dsh-light-ui[data-on=\"0\"] .dsh-light-icon { opacity: .45; }\n.dsh-light-panel {\n  position: absolute;\n  top: calc(100% + 6px);\n  left: 0;\n  box-sizing: border-box;\n  width: 240px;\n  max-width: calc(100vw - 16px);\n  padding: 14px;\n  border: 1px solid #9daa7e;\n  border-radius: 12px;\n  background: #f1f6e4;\n  color: #333824;\n  box-shadow: 0 3px 8px rgba(45, 41, 36, .15);\n}\n.dsh-light-align-right .dsh-light-panel { left: auto; right: 0; }\n.dsh-light-panel[hidden] { display: none; }\n.dsh-light-heading, .dsh-light-range-label { display: flex; justify-content: space-between; align-items: center; gap: 12px; }\n.dsh-light-heading strong { font-size: 14px; }\n.dsh-light-switch-label { display: flex; align-items: center; gap: 6px; cursor: pointer; }\n.dsh-light-panel fieldset { margin: 15px 0; padding: 0; border: 0; min-width: 0; }\n.dsh-light-panel legend { margin-bottom: 7px; padding: 0; }\n.dsh-light-modes { display: flex; gap: 4px; }\n.dsh-light-modes label { flex: 1; min-width: 0; cursor: pointer; }\n.dsh-light-modes input { position: absolute; opacity: 0; }\n.dsh-light-modes span { display: block; text-align: center; padding: 7px 3px; border: 1px solid #bdcba6; border-radius: 7px; }\n.dsh-light-modes input:checked + span { background: #a7b07b; border-color: #718149; }\n.dsh-light-panel input[type=\"range\"] { display: block; width: 100%; margin: 9px 0 0; accent-color: #475e29; }\n.dsh-light-panel input[type=\"checkbox\"] { accent-color: #475e29; }\n.dsh-light-trigger:focus-visible, .dsh-light-panel input:focus-visible { outline: 2px solid #475e29; outline-offset: 2px; }\n.dsh-light-modes input:focus-visible + span { outline: 2px solid #475e29; outline-offset: 2px; }\n@media (prefers-reduced-motion: reduce) {\n  .dsh-deco-stage .dsh-lamp-beam, .dsh-deco-stage .dsh-lamp-cutout { transition: none; }\n}\n\n/* Home-only floor vignette. Coordinates are scaled together by mountScene. */\n.dsh-home-scene {\n  position: fixed;\n  width: 750px;\n  height: 310px;\n  z-index: 34;\n  pointer-events: none;\n  transform-origin: bottom left;\n  visibility: hidden;\n}\n.dsh-home-scene[data-visible=\"1\"] { visibility: visible; }\n.dsh-home-scene img { position: absolute; display: block; height: auto; pointer-events: none; user-select: none; }\n.dsh-home-chair { left: -20px; bottom: 0; width: 240px; }\n.dsh-home-dog { left: 80px; bottom: 0; width: 225px; }\n.dsh-home-drawer { right: 16px; bottom: 10px; width: 190px; }\n.dsh-home-bowl { right: 54px; bottom: 192px; width: 115px; }\n.dsh-home-cat { right: 177px; bottom: 4px; width: 92px; }\nbody[data-dsh-global=\"1\"] .dsh-home-scene,\nbody[data-dsh-modal=\"1\"] .dsh-home-scene,\nbody[data-ds-dark-theme] .dsh-home-scene { visibility: hidden !important; }\n/* Keep the native hero layout and workspace/mode controls in place. */\nbody:not([data-ds-dark-theme]) [data-conversation-content][data-content-phase=\"hero\"] [class*=\"_headline\"]:has([class*=\"_titleGroup\"][data-dsh-greeting]) [class*=\"_fishHitbox\"],\nbody:not([data-ds-dark-theme]) [data-conversation-content][data-content-phase=\"hero\"] [class*=\"_titleGroup\"][data-dsh-greeting] > span { display: none; }\nbody:not([data-ds-dark-theme]) [data-conversation-content][data-content-phase=\"hero\"] [class*=\"_titleGroup\"][data-dsh-greeting] {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n  text-align: center;\n  color: var(--dsk-border-frame, #475e29);\n}\n.dsh-home-greeting { display: flex; flex-direction: column; align-items: center; max-width: 520px; }\n.dsh-home-greeting-title { font-size: 26px; font-weight: 600; line-height: 1.3; margin-bottom: 10px; }\n.dsh-home-greeting-welcome, .dsh-home-greeting-detail {\n  color: var(--dsk-text-primary, #333824);\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 1.6;\n}\nbody[data-ds-dark-theme] .dsh-home-greeting { display: none; }\n@media (prefers-reduced-motion: reduce) {\n  .dsh-home-scene { animation: none !important; transition: none !important; }\n}\n";
    const IMG = {"lamp": "data:image/webp;base64,", "shelf": "data:image/webp;base64,", "vine": "data:image/webp;base64,", "tree": "data:image/webp;base64,", "chair": "data:image/png;base64,", "rug": "data:image/webp;base64,", "westie": "data:image/webp;base64,", "drawer": "data:image/webp;base64,", "bowl": "data:image/webp;base64,", "cat": "data:image/webp;base64,", "head": "data:image/webp;base64,", "lampCutout": "data:image/png;base64,", "lampBeam": "data:image/png;base64,", "lampBeamSoft": "data:image/png;base64,", "lampRainbowMask": "data:image/png;base64,", "sleepingDog": "data:image/png;base64,", "watchingCat": "data:image/png;base64,", "homeChair": "data:image/png;base64,"};
    const HOME_LOCALE = {"en": {"morning": "Good morning! 🌿", "afternoon": "Good afternoon! 🌿", "evening": "Good evening! 🌿", "welcome": "Let's start a new conversation.", "detail": "Take a moment to gather your thoughts and explore new ideas."}, "zh": {"morning": "早安！ 🌿", "noon": "午安！ 🌿", "afternoon": "下午好！ 🌿", "evening": "晚上好！ 🌿", "welcome": "来开始一个新会话吧～", "detail": "在窗边小憩片刻，整理思路，探索新的灵感。"}};
/* ============================================================================
   Desk Scene (Mossy) — 挂载逻辑（Host 注入版 / Client 插件版共用）
   单一源码：desk-scene-ui/build.py 会把它分别包进
     - ~/.dsh/profiles/node_modules/@local/desk-scene/lib/design.js  (Host 版)
     - desk-scene-ui/client.js                                        (Client 版)

   mountScene(CSS, IMG) → dispose()
     CSS: Client 版传整包 CSS；Host 版传 null（样式由宿主 index.html 注入）
     IMG: {lamp,shelf,vine,tree,chair,rug,westie,drawer,bowl,cat} 的 URL / data URL

   设计要点
   - 面板/列等结构元素由「类名片段」找到后打上 data-dsh-* 属性，
     CSS 只依赖这些运行时标记，应用升级换掉 CSS Modules 哈希也不影响。
   - 顶部桌搭（灯 / 架子 / 垂吊）挂在 [data-dsh-frame] 内，层级 20：
     压在面板墨线之上、文字之下（灯的暖光半透明，正文仍清晰）。
   - 植物挂在侧边栏内容根里，z-index:-1，垫在会话行下面。
   - 猫 / 椅子 / 西高地 / 抽屉 / 鱼缸是 body 级 fixed 图层（40），
     锚定输入卡片的 rect，并根据左右可用空间自动缩放 / 隐藏。
   - 全局页面（[data-global-panel]）：桌搭隐藏，台灯按主面板居中（避开右上角按钮）；
     模态层（设置等）：整桌隐藏，保证按钮与内容不被压住。
   ============================================================================ */
function mountScene(CSS, IMG, HOME_LOCALE) {
  if (document.getElementById('dsh-desk-root')) return null;

  var doc = document;
  var body = doc.body;
  if (!body) return null;

  /* ---------- 基础工具 ---------- */
  function make(tag, cls) {
    var e = doc.createElement(tag);
    if (cls) e.className = cls;
    return e;
  }
  function makeImg(cls, src) {
    var e = make('img', cls);
    e.src = src;
    e.alt = '';
    e.draggable = false;
    return e;
  }

  /* ---------- 样式（Client 版才注入；Host 版由 index.html 提供） ---------- */
  var styleNode = null;
  if (CSS && !doc.getElementById('dsh-desk-scene')) {
    styleNode = make('style');
    styleNode.id = 'dsh-desk-scene';
    styleNode.textContent = CSS;
    (doc.head || doc.documentElement).appendChild(styleNode);
  }

  /* ---------- 标记节点（重复挂载守卫） ---------- */
  var marker = make('div');
  marker.id = 'dsh-desk-root';
  marker.setAttribute('aria-hidden', 'true');
  marker.style.display = 'none';
  body.appendChild(marker);

  /* ---------- 顶部桌搭：架子 / 垂吊 / 台灯 ---------- */
  var stage = make('div', 'dsh-deco-stage');
  var shelf = makeImg('dsh-deco-shelf', IMG.shelf);
  var vine = makeImg('dsh-deco-vine', IMG.vine);
  var lamp = makeImg('dsh-deco-lamp', IMG.lamp);
  stage.appendChild(shelf);
  stage.appendChild(vine);
  stage.appendChild(lamp);

  /* The original composite is kept untouched for the exact default rendering. */
  var lampBeam = make('div', 'dsh-deco-lamp dsh-lamp-beam');
  var lampCutout = makeImg('dsh-deco-lamp dsh-lamp-cutout', IMG.lampCutout || IMG.lamp);
  lampBeam.setAttribute('aria-hidden', 'true');
  if (IMG.lampBeam) {
    lampBeam.style.setProperty('--dsh-beam-image', 'url(' + JSON.stringify(IMG.lampBeam) + ')');
    lampBeam.style.setProperty('--dsh-beam-soft', 'url(' + JSON.stringify(IMG.lampBeamSoft || IMG.lampBeam) + ')');
    lampBeam.style.setProperty('--dsh-rainbow-mask', 'url(' + JSON.stringify(IMG.lampRainbowMask || IMG.lampBeam) + ')');
  }
  stage.appendChild(lampBeam);
  stage.appendChild(lampCutout);

  var lightUI = make('div', 'dsh-light-ui');
  var lightButton = make('button', 'dsh-light-trigger dsh-btn-outline');
  lightButton.type = 'button';
  lightButton.setAttribute('aria-expanded', 'false');
  lightButton.setAttribute('aria-controls', 'dsh-light-panel');
  lightButton.innerHTML = '<svg class="dsh-light-icon" viewBox="0 0 24 24" aria-hidden="true"><defs><linearGradient id="dsh-light-rainbow" x1="0" x2="1" y1="0" y2="0"><stop stop-color="#e8a7a2"/><stop offset=".25" stop-color="#e7d38c"/><stop offset=".5" stop-color="#abd1ae"/><stop offset=".75" stop-color="#a9c8e7"/><stop offset="1" stop-color="#d3b2df"/></linearGradient></defs><path d="M12 2v3M4 13a8 8 0 0 1 16 0c-3 2.4-13 2.4-16 0Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><path class="dsh-light-icon-glow" d="M5.2 13.4c2.4 1.3 11.2 1.3 13.6 0L21 21H3Z"/><path d="M8 18l-1 2m5-2v3m4-3 1 2" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg><span>Adjust light</span>';
  var lightPanel = make('div', 'dsh-light-panel');
  lightPanel.id = 'dsh-light-panel';
  lightPanel.hidden = true;
  lightPanel.innerHTML = '<div class="dsh-light-heading"><strong>Light</strong><label class="dsh-light-switch-label"><span>On</span><input type="checkbox" role="switch" aria-label="Light on"></label></div>' +
    '<fieldset><legend>Color</legend><div class="dsh-light-modes">' +
    '<label><input type="radio" name="dsh-light-mode" value="warm"><span>Warm</span></label>' +
    '<label><input type="radio" name="dsh-light-mode" value="white"><span>White</span></label>' +
    '<label><input type="radio" name="dsh-light-mode" value="rainbow"><span>Rainbow</span></label></div></fieldset>' +
    '<label class="dsh-light-range-label" for="dsh-light-range"><span>Beam size</span><output for="dsh-light-range"></output></label>' +
    '<input id="dsh-light-range" type="range" min="50" max="150" step="5">';
  lightUI.appendChild(lightButton);
  lightUI.appendChild(lightPanel);
  body.appendChild(lightUI);

  var lightSwitch = lightPanel.querySelector('[role="switch"]');
  var lightRange = lightPanel.querySelector('input[type="range"]');
  var lightOutput = lightPanel.querySelector('output');
  var lightModes = lightPanel.querySelectorAll('input[type="radio"]');
  var lightState = { on: true, mode: 'warm', sizes: { warm: 130, white: 100, rainbow: 100 } };
  var lightStorageKey = 'dsh-desk-light-v2';
  try {
    var stored = window.localStorage.getItem(lightStorageKey);
    var legacyLight = !stored && JSON.parse(window.localStorage.getItem('dsh-desk-light-v1') || 'null');
    var savedLight = JSON.parse(stored || 'null');
    // Apply the new default once, retaining prior white/rainbow sizes.
    if (!stored && legacyLight) {
      ['white', 'rainbow'].forEach(function (mode) {
        var value = legacyLight.sizes && legacyLight.sizes[mode];
        if (typeof value === 'number' && isFinite(value)) lightState.sizes[mode] = Math.max(50, Math.min(150, Math.round(value / 5) * 5));
      });
      window.localStorage.setItem(lightStorageKey, JSON.stringify(lightState));
    }
    if (savedLight && typeof savedLight.on === 'boolean') lightState.on = savedLight.on;
    if (savedLight && ['warm', 'white', 'rainbow'].indexOf(savedLight.mode) !== -1) lightState.mode = savedLight.mode;
    ['warm', 'white', 'rainbow'].forEach(function (mode) {
      var value = savedLight && savedLight.sizes && savedLight.sizes[mode];
      if (typeof value === 'number' && isFinite(value)) lightState.sizes[mode] = Math.max(50, Math.min(150, Math.round(value / 5) * 5));
    });
  } catch (err) { /* Storage can be disabled, unavailable, or malformed. */ }

  function renderLight(save) {
    var split = !!(IMG.lampCutout && IMG.lampBeam);
    var original = !split; /* All beam sizes use the softened, rounded ending. */
    lamp.style.visibility = original ? '' : 'hidden';
    lampBeam.style.display = !original && lightState.on ? 'block' : 'none';
    lampCutout.style.display = original ? 'none' : 'block';
    lampBeam.setAttribute('data-mode', lightState.mode);
    lampBeam.style.setProperty('--dsh-beam-scale', String(lightState.sizes[lightState.mode] / 100));
    lightUI.setAttribute('data-mode', lightState.mode);
    lightUI.setAttribute('data-on', lightState.on ? '1' : '0');
    lightButton.setAttribute('aria-label', 'Adjust light, ' + (lightState.on ? lightState.mode : 'off'));
    lightSwitch.checked = lightState.on;
    lightRange.value = String(lightState.sizes[lightState.mode]);
    lightOutput.textContent = lightState.sizes[lightState.mode] + '%';
    for (var i = 0; i < lightModes.length; i++) lightModes[i].checked = lightModes[i].value === lightState.mode;
    if (save) {
      try { window.localStorage.setItem(lightStorageKey, JSON.stringify(lightState)); } catch (err) { /* private mode */ }
    }
  }
  function closeLight(focus) {
    lightPanel.hidden = true;
    lightButton.setAttribute('aria-expanded', 'false');
    if (focus && lightUI.style.display !== 'none') lightButton.focus();
  }
  lightButton.addEventListener('click', function () {
    if (!lightPanel.hidden) return closeLight(false);
    lightPanel.hidden = false;
    lightButton.setAttribute('aria-expanded', 'true');
    lightSwitch.focus();
  });
  lightSwitch.addEventListener('change', function () { lightState.on = lightSwitch.checked; renderLight(true); });
  lightRange.addEventListener('input', function () { lightState.sizes[lightState.mode] = Number(lightRange.value); renderLight(true); });
  for (var lm = 0; lm < lightModes.length; lm++) lightModes[lm].addEventListener('change', function (event) {
    lightState.mode = event.target.value; renderLight(true);
  });
  function lightOutside(event) { if (!lightPanel.hidden && !lightUI.contains(event.target)) closeLight(false); }
  function lightKey(event) {
    if (event.key === 'Escape' && !lightPanel.hidden) { event.preventDefault(); event.stopPropagation(); closeLight(true); }
  }
  doc.addEventListener('pointerdown', lightOutside, true);
  doc.addEventListener('keydown', lightKey, true);
  renderLight(false);

  /* ---------- 侧边栏植物 ---------- */
  var tree = makeImg('dsh-deco-tree', IMG.tree);

  /* ---------- 面板描边覆盖层 ----------
     面板内可能有 iframe / 网页预览 / 原生控件，它们会画到边框上把墨线盖掉。
     这一层把三栏的描边"再画一遍"在最上层（宠物之下），保证任何内容都不会越出/盖住 stroke。 */
  var frameLines = make('div', 'dsh-frame-lines');
  frameLines.setAttribute('aria-hidden', 'true');
  var frameLineEls = {};
  ['sidebar', 'center', 'rightbar'].forEach(function (role) {
    var ln = make('div', 'dsh-frame-line');
    ln.setAttribute('data-for', role);
    frameLines.appendChild(ln);
    frameLineEls[role] = ln;
  });
  body.appendChild(frameLines);

  /* ---------- 宠物层 ---------- */
  var pets = make('div', 'dsh-pets');
  var rug = makeImg('dsh-pets-rug', IMG.rug);
  var chair = makeImg('dsh-pets-chair', IMG.chair);
  var westie = makeImg('dsh-pets-westie', IMG.westie);
  var drawer = makeImg('dsh-pets-drawer', IMG.drawer);
  var bowl = makeImg('dsh-pets-bowl', IMG.bowl);

  /* 睡猫：可点击（点一下收进界面变成小猫头） */
  var catBtn = make('button', 'dsh-cat-btn');
  catBtn.type = 'button';
  catBtn.setAttribute('aria-label', "Hi, I'm Julie's orange tabby. Click to tuck me away.");
  var catImg = makeImg('dsh-cat-img', IMG.cat);
  catBtn.appendChild(catImg);

  /* 收起态：输入框右侧的小猫头 */
  var HEAD_W = 32;
  var HEAD_H = 22;
  var headBtn = make('button', 'dsh-cathead-btn');
  headBtn.type = 'button';
  headBtn.setAttribute('aria-label', 'Show the orange tabby');
  var headImg = makeImg('dsh-cathead-img', IMG.head);
  headBtn.appendChild(headImg);

  pets.appendChild(rug);
  pets.appendChild(chair);
  pets.appendChild(westie);
  pets.appendChild(drawer);
  pets.appendChild(bowl);
  pets.appendChild(catBtn);
  pets.appendChild(headBtn);
  body.appendChild(pets);

  /* Home is a separate, non-interactive floor scene, never a replacement for
     the native greeting or composer. */
  var homeScene = make('div', 'dsh-home-scene');
  homeScene.setAttribute('aria-hidden', 'true');
  homeScene.appendChild(makeImg('dsh-home-chair', IMG.homeChair || IMG.chair));
  homeScene.appendChild(makeImg('dsh-home-dog', IMG.sleepingDog));
  homeScene.appendChild(makeImg('dsh-home-drawer', IMG.drawer));
  homeScene.appendChild(makeImg('dsh-home-bowl', IMG.bowl));
  homeScene.appendChild(makeImg('dsh-home-cat', IMG.watchingCat));
  body.appendChild(homeScene);
  var homePhase = null, homeContent = null, homeSeat = null, homeSeatRect = null;
  var homeFade = null, homeFlip = null, homeRaf = 0;
  var homeGreeting = null;

  /* 提示气泡挂在 body（不被宠物层的裁切影响） */
  var catTip = make('div', 'dsh-cat-tip');
  catTip.setAttribute('role', 'tooltip');
  catTip.setAttribute('aria-hidden', 'true');
  body.appendChild(catTip);
  body.setAttribute('data-dsh-cat', 'expanded');

  /* 每张图的自然尺寸（用于按基准宽度等比缩放） */
  var PET = {
    rug: { w: 436, h: 141, base: 186, z: 10 },
    chair: { w: 259, h: 280, base: 384, z: 11 },
    westie: { w: 218, h: 295, base: 227, z: 12 },
    drawer: { w: 281, h: 279, base: 232, z: 13 },
    bowl: { w: 212, h: 216, base: 148, z: 14 },
    cat: { w: 357, h: 175, base: 188, z: 15 }
  };
  /* 依次设置尺寸：base 宽按比例缩放，高度按图片真实比例 */
  function sizePets(scale) {
    var list = [
      [rug, PET.rug, scale],
      [chair, PET.chair, scale],
      [westie, PET.westie, scale],
      [drawer, PET.drawer, scale],
      [bowl, PET.bowl, scale],
      [catBtn, PET.cat, scale]
    ];
    for (var i = 0; i < list.length; i++) {
      var img = list[i][0];
      var meta = list[i][1];
      var s = list[i][2];
      var w = meta.base * s;
      var h = w * (meta.h / meta.w);
      img.style.width = w.toFixed(1) + 'px';
      img.style.height = h.toFixed(1) + 'px';
      img.style.zIndex = String(meta.z);
      img.__dshH = h;
    }
  }

  /* ---------- 运行时标记（把应用结构元素交给 CSS） ---------- */
  var frameEl = null;
  var mainEl = null;
  var sidebarRootEl = null;
  var chatBodyEl = null;

  function findFrame() {
    var tagged = doc.querySelector('[data-dsh-frame]');
    if (tagged) return tagged;
    var root = doc.getElementById('root');
    if (!root) return null;
    var first = root.firstElementChild;
    if (!first) return null;
    var cls = typeof first.className === 'string' ? first.className : '';
    var cand = cls.indexOf('_frame') >= 0 ? first : first.querySelector('[class*="_frame"]');
    if (cand) cand.setAttribute('data-dsh-frame', '');
    return cand;
  }

  function tagDom() {
    if (!frameEl || !doc.documentElement.contains(frameEl)) frameEl = findFrame();
    if (frameEl && stage.parentNode !== frameEl) frameEl.appendChild(stage);

    if (frameEl) {
      var kids = frameEl.children;
      for (var i = 0; i < kids.length; i++) {
        var c = kids[i];
        if (!c || c.nodeType !== 1) continue;
        if (c.hasAttribute('data-dsh-col')) continue;
        var cn = typeof c.className === 'string' ? c.className : '';
        if (cn.indexOf('_sidebarCol') >= 0) c.setAttribute('data-dsh-col', 'sidebar');
        else if (cn.indexOf('_centerCol') >= 0) c.setAttribute('data-dsh-col', 'center');
        else if (cn.indexOf('_rightbarCol') >= 0) c.setAttribute('data-dsh-col', 'rightbar');
      }
    }

    if (!mainEl || !doc.documentElement.contains(mainEl)) {
      mainEl = doc.querySelector('[data-dsh-main]');
      if (!mainEl) {
        var m = doc.querySelector('[class*="_mainPanel"]');
        if (m) {
          m.setAttribute('data-dsh-main', '');
          mainEl = m;
        }
      }
    }

    /* 侧边栏内容根：植物要挂进去垫底 */
    if (!sidebarRootEl || !doc.documentElement.contains(sidebarRootEl)) {
      sidebarRootEl = doc.querySelector('[data-dsh-sidebar]');
      if (!sidebarRootEl) {
        var slot = doc.querySelector('[data-slot="sidebar"]');
        var sr = slot ? slot.firstElementChild : null;
        if (sr) {
          sr.setAttribute('data-dsh-sidebar', '');
          sidebarRootEl = sr;
        }
      }
    }
    if (sidebarRootEl && tree.parentNode !== sidebarRootEl) sidebarRootEl.appendChild(tree);

    /* 会话正文根：用来自适应聊天列宽（横幅时保持绘本式的窄栏） */
    if (chatBodyEl && !doc.documentElement.contains(chatBodyEl)) chatBodyEl = null;
    if (!chatBodyEl) {
      var card = doc.querySelector('[data-composer-card]');
      if (card) {
        var anc = card.parentElement;
        while (anc && anc !== body) {
          var cls = typeof anc.className === 'string' ? anc.className : '';
          if (cls.indexOf('_body') >= 0 && anc.getAttribute('data-slot') === null) {
            anc.setAttribute('data-dsh-chat-body', '');
            chatBodyEl = anc;
            break;
          }
          anc = anc.parentElement;
        }
      }
    }
  }

  /* ---------- 模式判定 + 台灯位置 ---------- */
  var LAMP_W = 502;
  var LAMP_H = 347;
  var LAMP_HEAD_CENTER = 383.5; /* 灯罩中心在 502 宽图中的 x */
  var LAMP_BASE_LEFT = 386; /* 灯座左缘，原图坐标 */
  var LAMP_BASE_RIGHT = 429; /* 灯座右缘，原图坐标 */
  var LAMP_BASE_BOTTOM = 108; /* 灯座底缘，不是包含光束的图片底缘 */
  var lastGlobal = null;

  /* 右侧检查器面板是否展开（三栏并排） */
  function rightPanelOpen() {
    var rb = doc.querySelector('[data-dsh-col="rightbar"]');
    if (!rb) return false;
    var r = rb.getBoundingClientRect();
    return r.width > 40;
  }

  function applyMode() {
    var global = !!(mainEl && mainEl.hasAttribute('data-global-panel'));
    var modal = !!doc.querySelector('[role="dialog"][aria-modal="true"]');
    var rightOpen = rightPanelOpen();

    body.setAttribute('data-dsh-global', global ? '1' : '0');
    body.setAttribute('data-dsh-modal', modal ? '1' : '0');
    body.setAttribute('data-dsh-rightpanel', rightOpen ? '1' : '0');

    /* In constrained layouts keep the actual lamp base near the right of the
       current panel, not the center of its much wider transparent beam canvas. */
    var mainRect = mainEl.getBoundingClientRect();
    var compactPanel = mainRect.width < 850;
    if ((global || rightOpen || compactPanel) && !modal) {
      var r = mainRect;
      var headLimit = Math.max(120, r.width / 2 - 6);
      var sc = Math.min(1, headLimit / LAMP_HEAD_CENTER);
      var stageTop = stage.getBoundingClientRect().top;
      var lampHeader = !global && mainEl.querySelector('header[data-window-drag="true"]');
      var lineY = lampHeader ? lampHeader.getBoundingClientRect().bottom : null;
      if (lineY !== null) {
        var availH = lineY - stageTop - 2; /* 灯体位于分界线上方；光束可延伸到线下 */
        if (availH > 40) sc = Math.min(sc, availH / LAMP_BASE_BOTTOM);
      }
      var w = LAMP_W * sc;
      var h = LAMP_H * sc;
      var stageLeft = stage.getBoundingClientRect().left;
      var rightInset = Math.max(72, Math.min(180, r.width * 0.14));
      var baseRight = r.right - rightInset;
      var left = baseRight - LAMP_BASE_RIGHT * sc - stageLeft;
      lamp.style.width = w.toFixed(1) + 'px';
      lamp.style.height = h.toFixed(1) + 'px';
      lamp.style.left = left.toFixed(1) + 'px';
      lamp.style.right = 'auto';
      lamp.style.top = lineY !== null ? (lineY - stageTop - LAMP_BASE_BOTTOM * sc).toFixed(1) + 'px' : '';
    } else {
      lamp.style.width = '';
      lamp.style.height = '';
      lamp.style.left = '';
      lamp.style.right = '';
      var normalHeader = !global && mainEl.querySelector('header[data-window-drag="true"]');
      if (normalHeader && !modal) {
        var normalStageTop = stage.getBoundingClientRect().top;
        var normalLine = normalHeader.getBoundingClientRect().bottom;
        var normalScale = Math.min(1, Math.max(0.1, (normalLine - normalStageTop - 2) / LAMP_BASE_BOTTOM));
        if (normalScale < 1) {
          lamp.style.width = (LAMP_W * normalScale).toFixed(1) + 'px';
          lamp.style.height = (LAMP_H * normalScale).toFixed(1) + 'px';
        }
        lamp.style.top = (normalLine - normalStageTop - LAMP_BASE_BOTTOM * normalScale).toFixed(1) + 'px';
      } else lamp.style.top = '';
    }
    /* The artwork scales with the header, but beam size is independent of that
       adaptation. Re-anchor the full-size beam to the scaled shade opening. */
    lampCutout.style.width = lamp.style.width;
    lampCutout.style.height = lamp.style.height;
    lampCutout.style.left = lamp.style.left;
    lampCutout.style.right = lamp.style.right;
    lampCutout.style.top = lamp.style.top;
    var lampRect = lamp.getBoundingClientRect();
    var stageRect = stage.getBoundingClientRect();
    var beamOriginX = 365;
    var beamOriginY = lightState.mode === 'rainbow' ? 56 : 51;
    var lampScale = lampRect.width / LAMP_W;
    lampBeam.style.width = LAMP_W + 'px';
    lampBeam.style.height = LAMP_H + 'px';
    lampBeam.style.left = (lampRect.left - stageRect.left + beamOriginX * lampScale - beamOriginX).toFixed(1) + 'px';
    lampBeam.style.top = (lampRect.top - stageRect.top + beamOriginY * lampScale - beamOriginY).toFixed(1) + 'px';
    lampBeam.style.right = 'auto';
    positionLight(modal);
    lastGlobal = global;
    return global;
  }

  /* Find a free part of the header rather than intercepting existing controls. */
  function positionLight(modal) {
    var header = mainEl && mainEl.querySelector('header[data-window-drag="true"]');
    if (modal || body.hasAttribute('data-ds-dark-theme') || !header || !(IMG.lampCutout && IMG.lampBeam)) {
      closeLight(false);
      lightUI.style.display = 'none';
      return;
    }
    var hr = header.getBoundingClientRect();
    var lr = lamp.getBoundingClientRect();
    lightUI.style.display = '';
    var compactLight = lr.width / LAMP_W < 0.8 || hr.width < 720;
    lightUI.classList.toggle('dsh-light-compact', compactLight);
    lightButton.title = compactLight ? 'Adjust light' : '';
    var width = lightButton.getBoundingClientRect().width || (compactLight ? 35 : 128), height = 32;
    var top = Math.max(hr.top + 2, hr.bottom - height - 3);
    var min = Math.max(8, hr.left + 4), max = Math.min(window.innerWidth - width - 8, hr.right - width - 4);
    /* Keep the button's right edge 8px from the base as the lamp scales. */
    var baseLeft = lr.left + lr.width * LAMP_BASE_LEFT / LAMP_W;
    var desired = Math.max(min, Math.min(max, baseLeft - width - 8));
    var obstacles = header.querySelectorAll('button, a, input, select, textarea, [role="button"], [role="tab"], [tabindex]:not([tabindex="-1"])');
    var chosen = null;
    for (var delta = 0; delta <= Math.max(0, max - min) + 12 && chosen === null; delta += 8) {
      /* Never place the control over the lamp base if another tab is nearby. */
      var candidates = delta ? [desired - delta] : [desired];
      for (var j = 0; j < candidates.length; j++) {
        var x = candidates[j];
        if (x < min || x > max) continue;
        var clear = true;
        for (var k = 0; k < obstacles.length; k++) {
          var r = obstacles[k].getBoundingClientRect();
          if (r.width && r.height && x < r.right + 4 && x + width > r.left - 4 && top < r.bottom + 3 && top + height > r.top - 3) { clear = false; break; }
        }
        if (clear) { chosen = x; break; }
      }
    }
    if (chosen === null || hr.height < height || max < min) {
      closeLight(false);
      lightUI.style.display = 'none';
      return;
    }
    lightUI.style.display = '';
    lightUI.style.left = Math.round(chosen) + 'px';
    lightUI.style.top = Math.round(top) + 'px';
    lightUI.classList.toggle('dsh-light-align-right', chosen + 240 > window.innerWidth - 8);
  }

  /* 宠物图层按「中栏面板」裁切：三栏并排时狗/椅子/猫也不会溢出到左右面板 */
  function clipPets() {
    var cc = doc.querySelector('[data-dsh-col="center"]');
    if (!cc) { pets.style.clipPath = ''; return; }
    var r = cc.getBoundingClientRect();
    var top = Math.max(0, Math.round(r.top));
    var right = Math.max(0, Math.round(window.innerWidth - r.right));
    var bottom = Math.max(0, Math.round(window.innerHeight - r.bottom));
    var left = Math.max(0, Math.round(r.left));
    pets.style.clipPath = 'inset(' + top + 'px ' + right + 'px ' + bottom + 'px ' + left + 'px)';
  }

  /* ---------- 宠物锚定 ----------
     猫咪 / 猫头的底边永远贴着输入卡「顶部外描边」（just above input top outline）：
     用实时 rect 跟随，输入框高度变化（多行输入撑高）时猫也跟着走，
     不再做跳变过滤，否则撑高期间猫会掉队。 */
  /* 睡猫素材的「视觉落脚线」：paw/body 底缘在素材 y≈146/175，尾巴还往下挂到 172；
     对齐落脚线（而不是素材底边）到输入框顶边，视觉上才是真的趴在边框上，
     尾巴会自然垂在输入框上沿（卡内右上角是空白区，不会压到文字）。 */
  var CAT_REST_RATIO = 28.5 / 175;
  /* 垂直微调：+2 起步，用户 +10 → 12 */
  var CAT_SINK_PX = 12;
  var HEAD_BOTTOM_PAD = 0;  /* 猫头素材无底部透明边，直接贴住外描边 */

  function hidePets() {
    body.setAttribute('data-dsh-pets', '0');
    hideTip();
    if (catAnimating || ghostNodes.length) resetCatInstant(catState === 'collapsed' ? 'collapsed' : 'expanded');
  }

  /* ==========================================================================
     猫咪交互：默认趴着；输入框上方出现 UI（To-dos / 排队消息 / 其它 dock 内容）
     时自动收起成小猫头；点击猫可手动收起，点击猫头恢复。
     收起动效 460ms：0-100 压扁 → 100-380 右上缩小（两层残影 45/90ms）→ 380-460 回弹 2px。
     ========================================================================== */
  var catState = 'expanded'; /* expanded | collapsing | collapsed | expanding */
  var manualCollapsed = false;
  var catAnimating = false;
  var lastCardRect = null;
  var catTimer = null;
  var ghostNodes = [];
  var reduceMQ = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;

  function prefersReduced() {
    return !!(reduceMQ && reduceMQ.matches);
  }

  /* 输入框「上方」是否有 UI：conversation.input.dock 里任何可见条目
     （To-dos 面板、排队消息卡片等；chat stream 不在这里，不会误触发） */
  function composerUiAbove() {
    var dock = doc.querySelector('[data-slot="conversation.input.dock"]');
    if (!dock) return false;
    var kids = dock.children;
    for (var i = 0; i < kids.length; i++) {
      var k = kids[i];
      if (!k || k.nodeType !== 1) continue;
      var cs = window.getComputedStyle(k);
      if (cs.display === 'none' || cs.visibility === 'hidden' || cs.opacity === '0') continue;
      var r = k.getBoundingClientRect();
      if (r.height > 4 && r.width > 4) return true;
    }
    return false;
  }

  /* 输入框上方 dock UI（To-dos / 排队卡片等）的包围盒，用于避让 */
  function dockBounds() {
    var dock = doc.querySelector('[data-slot="conversation.input.dock"]');
    if (!dock) return null;
    var box = null;
    var kids = dock.children;
    for (var i = 0; i < kids.length; i++) {
      var k = kids[i];
      if (!k || k.nodeType !== 1) continue;
      var cs = window.getComputedStyle(k);
      if (cs.display === 'none' || cs.visibility === 'hidden') continue;
      var r = k.getBoundingClientRect();
      if (r.height <= 4 || r.width <= 4) continue;
      if (!box) box = { left: r.left, right: r.right, top: r.top, bottom: r.bottom };
      else {
        box.left = Math.min(box.left, r.left);
        box.right = Math.max(box.right, r.right);
        box.top = Math.min(box.top, r.top);
        box.bottom = Math.max(box.bottom, r.bottom);
      }
    }
    return box;
  }

  /* 小猫头落点：猫咪和输入框是一个整体 —— 永远趴在输入卡的右上角顶边上。
     · 纵向：底边永远贴在输入卡顶部外描边上（不再收进卡片内部）；
     · 横向：默认与睡猫同一右对齐（卡片右缘内 16px）；
       上方有 dock UI（To-dos / 排队卡片）时，往右挪到 dock 卡片右缘之外，
       避开任务卡右侧的删除/操作按钮，同时仍然压在输入框顶边上。 */
  function headTarget() {
    var r = lastCardRect;
    if (!r) return null;
    var iw = window.innerWidth;
    var cc = doc.querySelector('[data-dsh-col="center"]');
    var rightLimit = (cc ? cc.getBoundingClientRect().right : iw - 8) - 8;
    var leftMax = rightLimit - HEAD_W;
    /* 和输入卡右侧右对齐：右缘对齐卡片右边（让开 2px 外描边），永远咬在右上角 */
    var left = r.right - 2 - HEAD_W;
    left = Math.max(8, Math.min(left, leftMax));
    if (left < 8) left = 8;
    /* 正好趴在输入框顶部外描边上，再按用户微调往下 2px */
    var HEAD_SINK_PX = 2;
    var top = r.top + HEAD_BOTTOM_PAD - HEAD_H + HEAD_SINK_PX;
    return { left: left, top: top, width: HEAD_W, height: HEAD_H };
  }

  function clearCatTimer() {
    if (catTimer) { clearTimeout(catTimer); catTimer = null; }
  }

  function cancelCatAnims() {
    if (typeof catBtn.getAnimations !== 'function') return;
    var list = catBtn.getAnimations();
    for (var i = 0; i < list.length; i++) {
      try { list[i].cancel(); } catch (err) { /* ignore */ }
    }
  }

  function removeGhosts() {
    for (var i = 0; i < ghostNodes.length; i++) {
      var g = ghostNodes[i];
      if (g && g.parentNode) g.parentNode.removeChild(g);
    }
    ghostNodes = [];
  }

  function resetCatInstant(state) {
    clearCatTimer();
    removeGhosts();
    catAnimating = false;
    cancelCatAnims();
    catBtn.style.transform = '';
    catBtn.style.transformOrigin = '';
    catBtn.style.visibility = '';
    catState = state || 'expanded';
    body.setAttribute('data-dsh-cat', catState === 'collapsed' ? 'collapsed' : 'expanded');
  }

  function bounceHead() {
    if (!headBtn.animate || prefersReduced()) return;
    headBtn.animate([
      { transform: 'translateY(0px)' },
      { transform: 'translateY(-2px)', offset: 0.45 },
      { transform: 'translateY(0px)' }
    ], { duration: 80, easing: 'ease-out' });
  }

  function collapseCat() {
    if (catState !== 'expanded' || !lastCardRect) return;
    var target = headTarget();
    if (!target) return;

    if (prefersReduced() || !catBtn.animate) {
      resetCatInstant('collapsed');
      bounceHead();
      return;
    }

    var from = catBtn.getBoundingClientRect();
    if (!from.width || !from.height) { resetCatInstant('collapsed'); return; }
    var dx = target.left - from.left;
    var dy = target.top - from.top;
    var sx = target.width / from.width;
    var sy = target.height / from.height;
    var EASE = 'cubic-bezier(0.22, 1, 0.36, 1)';

    catState = 'collapsing';
    catAnimating = true;
    body.setAttribute('data-dsh-cat', 'expanded'); /* 形变期间整猫仍可见 */
    catBtn.style.transformOrigin = 'top left';

    try {
      catBtn.animate([
        { transform: 'scale(1,1)', offset: 0, easing: 'ease-out' },
        { transform: 'scale(0.9,1.08)', offset: 0.263, easing: EASE },
        { transform: 'translate(' + dx.toFixed(1) + 'px,' + dy.toFixed(1) + 'px) scale(' + sx.toFixed(3) + ',' + sy.toFixed(3) + ')', offset: 1 }
      ], { duration: 380, easing: 'linear', fill: 'forwards' });
    } catch (err) { /* ignore */ }

    /* 两层残影：复制整猫，延迟 45ms / 90ms 跟随同一路径，透明度 0.22 → 0 */
    var delays = [45, 90];
    for (var i = 0; i < delays.length; i++) {
      var ghost = catImg.cloneNode(true);
      ghost.className = 'dsh-cat-ghost';
      ghost.style.left = from.left + 'px';
      ghost.style.top = from.top + 'px';
      ghost.style.width = from.width + 'px';
      ghost.style.height = from.height + 'px';
      ghost.style.opacity = '0';
      ghost.style.transformOrigin = 'top left';
      pets.appendChild(ghost);
      ghostNodes.push(ghost);
      if (ghost.animate) {
        try {
          ghost.animate([
            { opacity: 0, transform: 'scale(1,1)', offset: 0, easing: 'ease-out' },
            { opacity: 0.22, transform: 'scale(0.9,1.08)', offset: 0.263, easing: EASE },
            { opacity: 0, transform: 'translate(' + dx.toFixed(1) + 'px,' + dy.toFixed(1) + 'px) scale(' + sx.toFixed(3) + ',' + sy.toFixed(3) + ')', offset: 1 }
          ], { duration: 380, delay: 100 + delays[i], easing: 'linear', fill: 'both' });
        } catch (err) { /* ignore */ }
      }
    }

    clearCatTimer();
    catTimer = setTimeout(function () {
      catTimer = null;
      if (catState !== 'collapsing') return;
      cancelCatAnims();
      catBtn.style.visibility = 'hidden';
      catBtn.style.transform = '';
      catBtn.style.transformOrigin = '';
      catAnimating = false;
      catState = 'collapsed';
      body.setAttribute('data-dsh-cat', 'collapsed');
      removeGhosts();
      bounceHead();
    }, 380);
  }

  function expandCat() {
    if (catState === 'expanded' || catState === 'collapsing') return;
    if (prefersReduced() || !catBtn.animate) {
      resetCatInstant('expanded');
      return;
    }
    clearCatTimer();
    removeGhosts();
    cancelCatAnims();
    catState = 'expanding';
    catAnimating = true;
    catBtn.style.visibility = '';
    catBtn.style.transformOrigin = 'bottom center';
    body.setAttribute('data-dsh-cat', 'expanded');
    try {
      catBtn.animate([
        { opacity: 0, transform: 'scale(0.55,0.55)', offset: 0 },
        { opacity: 1, transform: 'scale(1,1)', offset: 1 }
      ], { duration: 220, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' });
    } catch (err) { /* ignore */ }
    catTimer = setTimeout(function () {
      catTimer = null;
      if (catState !== 'expanding') return;
      cancelCatAnims();
      catBtn.style.transform = '';
      catBtn.style.transformOrigin = '';
      catAnimating = false;
      catState = 'expanded';
    }, 230);
  }

  /* 同步一次猫咪状态：输入框上方有 UI / 手动收起 / 恢复 */
  function updateCat() {
    if (!lastCardRect) return;
    if (body.getAttribute('data-dsh-pets') !== '1') return;
    if (catAnimating) return;
    var auto = composerUiAbove();
    var wantCollapsed = auto || manualCollapsed;
    if (wantCollapsed && catState === 'expanded') collapseCat();
    else if (!wantCollapsed && catState === 'collapsed') expandCat();
    if (body.getAttribute('data-dsh-cat-tip') === '1') updateTipText(auto);
  }

  /* ---------- 提示气泡 ---------- */
  function tipText(auto) {
    if (catState === 'collapsed') {
      return auto ? 'I will pop back when the task card is gone.' : 'Click to bring me back.';
    }
    return "Hi, I'm Julie's orange tabby \u2014 click to tuck me away.";
  }

  function updateTipText(auto) {
    if (body.getAttribute('data-dsh-cat-tip') !== '1') return;
    catTip.textContent = tipText(typeof auto === 'boolean' ? auto : composerUiAbove());
    positionTip();
  }

  function activeCatEl() {
    return (catState === 'collapsed') ? headBtn : catBtn;
  }

  function positionTip() {
    var el = activeCatEl();
    if (!el) return;
    var r = el.getBoundingClientRect();
    var tw = catTip.offsetWidth;
    var th = catTip.offsetHeight;
    var left = r.left + r.width / 2 - tw / 2;
    left = Math.max(8, Math.min(left, window.innerWidth - tw - 8));
    var top = r.top - th - 10;
    if (top < 6) top = r.bottom + 10;
    catTip.style.left = left + 'px';
    catTip.style.top = top + 'px';
  }

  function showTip() {
    catTip.textContent = tipText(composerUiAbove());
    body.setAttribute('data-dsh-cat-tip', '1');
    positionTip();
  }

  function hideTip() {
    body.setAttribute('data-dsh-cat-tip', '0');
  }

  catBtn.addEventListener('mouseenter', showTip);
  catBtn.addEventListener('mouseleave', hideTip);
  catBtn.addEventListener('focus', showTip);
  catBtn.addEventListener('blur', hideTip);
  headBtn.addEventListener('mouseenter', showTip);
  headBtn.addEventListener('mouseleave', hideTip);
  headBtn.addEventListener('focus', showTip);
  headBtn.addEventListener('blur', hideTip);

  catBtn.addEventListener('click', function () {
    if (catAnimating || catState !== 'expanded') return;
    manualCollapsed = true;
    collapseCat();
    hideTip();
  });

  headBtn.addEventListener('click', function () {
    if (catAnimating) return;
    /* 自动收起期间（上方有 UI）不展开，避免刚展开又被收起 */
    if (composerUiAbove()) {
      catTip.textContent = 'I will pop back when the task card is gone.';
      body.setAttribute('data-dsh-cat-tip', '1');
      positionTip();
      return;
    }
    manualCollapsed = false;
    expandCat();
    hideTip();
  });

  function layoutPets(global) {
    var card = doc.querySelector('[data-composer-card]');
    if (!card || global || body.getAttribute('data-dsh-modal') === '1' ||
        doc.querySelector('[data-conversation-content][data-content-phase="hero"]')) return hidePets();
    var r = card.getBoundingClientRect();
    if (!r.width || !r.height) return;
    var iw = window.innerWidth;
    var ih = window.innerHeight;

    /* 只有输入卡片停在底部（真实会话）时才摆宠物；首页居中的 hero 卡片不摆 */
    var docked = r.bottom > ih - 170 && r.top > ih * 0.45;
    if (docked) body.setAttribute('data-dsh-docked', '1');
    else body.removeAttribute('data-dsh-docked');
    if (!docked) return hidePets();

    var sideCol = doc.querySelector('[data-dsh-col="sidebar"]');
    var centerCol = doc.querySelector('[data-dsh-col="center"]');
    var sbRight = sideCol ? sideCol.getBoundingClientRect().right : 0;
    /* 右侧空间以中栏面板右缘为准：右侧检查器面板展开时不再把宠物塞到它上面 */
    var rightBound = centerCol ? centerCol.getBoundingClientRect().right : iw - 16;
    var leftRoom = r.left - sbRight - 18;
    var rightRoom = rightBound - r.right - 14;

    var scale = Math.min(leftRoom / 285, rightRoom / 255, 1.05);
    scale = Math.max(0.5, Math.min(scale, 1));
    sizePets(scale);

    /* 侧边宠物允许压住一侧面板边框（参考图里绿椅就压在面板线上），
       只要口袋还有 90px 就按 0.55 的最小比例出现，不容易"消失"。 */
    var showLeft = leftRoom >= 90;
    var showRight = rightRoom >= 80;

    /* 左侧：椅子 / 西高地 / 地毯 */
    if (showLeft) {
      rug.style.display = '';
      chair.style.display = '';
      westie.style.display = '';
      rug.style.right = iw - (r.left - 10) + 'px';
      rug.style.left = 'auto';
      rug.style.bottom = '84px';
      chair.style.right = iw - (r.left - 20) + 'px';
      chair.style.left = 'auto';
      chair.style.bottom = '108px';
      westie.style.right = iw - (r.left - 34) + 'px';
      westie.style.left = 'auto';
      westie.style.bottom = '94px';
    } else {
      rug.style.display = 'none';
      chair.style.display = 'none';
      westie.style.display = 'none';
    }

    /* 右侧：抽屉 + 鱼缸 */
    if (showRight) {
      var drawerW = parseFloat(drawer.style.width) || 0;
      var bowlW = parseFloat(bowl.style.width) || 0;
      /* 位置贴输入卡右侧，但不许冲出窗口右缘 */
      var drawerLeft = Math.min(r.right + 18, iw - 10 - drawerW);
      var bowlLeft = Math.min(r.right + 34, iw - 10 - bowlW);
      drawer.style.display = '';
      bowl.style.display = '';
      drawer.style.left = drawerLeft + 'px';
      drawer.style.right = 'auto';
      drawer.style.bottom = '54px';
      /* 鱼缸居中放在绿柜顶面上：素材四边各有 ~2px 透明边，按内容边精确贴合 */
      bowlLeft = Math.max(10, drawerLeft + (drawerW - bowlW) / 2);
      bowl.style.left = bowlLeft + 'px';
      bowl.style.right = 'auto';
      var DRAWER_TOP_PAD = 2 / 279;   /* drawer.png 顶部透明边比例 */
      var BOWL_BOTTOM_PAD = 2 / 216;  /* bowl.png 底部透明边比例 */
      var BOWL_SINK_PX = 8;           /* 用户微调：鱼缸整体再往下 8px */
      bowl.style.bottom = (54 + drawer.__dshH * (1 - DRAWER_TOP_PAD) - bowl.__dshH * BOWL_BOTTOM_PAD - 1 - BOWL_SINK_PX) + 'px';
    } else {
      drawer.style.display = 'none';
      bowl.style.display = 'none';
    }

    /* 猫：底边正好趴在输入卡顶部外描边上（收起态换成右侧小猫头） */
    lastCardRect = r;
    if (!catAnimating) {
      catBtn.style.top = (r.top - catBtn.__dshH * (1 - CAT_REST_RATIO) + CAT_SINK_PX) + 'px';
      catBtn.style.right = (iw - r.right + 16) + 'px';
      catBtn.style.left = 'auto';
      catBtn.style.bottom = 'auto';
      var target = headTarget();
      if (target) {
        headBtn.style.left = target.left + 'px';
        headBtn.style.top = target.top + 'px';
        headBtn.style.right = 'auto';
        headBtn.style.bottom = 'auto';
      }
    }

    body.setAttribute('data-dsh-pets', '1');
    updateCat();
  }

  /* ---------- 侧边栏植物：只占用「列表底部 ~ 账号行」之间的空白，不压文字 ---------- */
  var TREE_RATIO = 366 / 222; /* 素材高宽比 */
  /* 面板描边覆盖层：每帧同步三栏的 rect、边框宽度、圆角、颜色 */
  function layoutFrameLines() {
    if (!frameLines) return;
    var hidden = body.getAttribute('data-dsh-modal') === '1';
    frameLines.style.display = hidden ? 'none' : '';
    if (hidden) return;
    for (var role in frameLineEls) {
      var col = doc.querySelector('[data-dsh-col="' + role + '"]');
      var ln = frameLineEls[role];
      if (!col) { ln.style.display = 'none'; continue; }
      var r = col.getBoundingClientRect();
      var cs = window.getComputedStyle(col);
      var bw = parseFloat(cs.borderTopWidth) || 0;
      if (r.width < 4 || r.height < 4 || cs.display === 'none' || bw <= 0) {
        ln.style.display = 'none';
        continue;
      }
      ln.style.display = 'block';
      ln.style.left = r.left + 'px';
      ln.style.top = r.top + 'px';
      ln.style.width = r.width + 'px';
      ln.style.height = r.height + 'px';
      ln.style.borderStyle = 'solid';
      ln.style.borderWidth =
        cs.borderTopWidth + ' ' + cs.borderRightWidth + ' ' +
        cs.borderBottomWidth + ' ' + cs.borderLeftWidth;
      ln.style.borderColor = cs.borderTopColor;
      ln.style.borderRadius =
        cs.borderTopLeftRadius + ' ' + cs.borderTopRightRadius + ' ' +
        cs.borderBottomRightRadius + ' ' + cs.borderBottomLeftRadius;
    }
  }

  /* 顶部桌搭：架子/垂吊贴在会话页头的 tab 分界线（header 底边框）上。
     位置动态算，不写死 top —— 窗口尺寸 / 标题栏高度变化时都刚好坐在线上。 */
  var SHELF_BASE_TOP = 31;
  var VINE_BASE_TOP = 85;
  function layoutStage() {
    if (!stage || !shelf) return;
    var header = doc.querySelector('[data-dsh-main] header[data-window-drag="true"]');
    if (!header) { shelf.style.top = ''; vine.style.top = ''; return; }
    var hr = header.getBoundingClientRect();
    var sr = stage.getBoundingClientRect();
    var shelfH = shelf.__dshH || 66;
    var top = hr.bottom - sr.top - shelfH; /* 木板底边正好压在分界线上 */
    if (!isFinite(top)) return;
    shelf.style.top = Math.round(top) + 'px';
    vine.style.top = Math.round(top + (VINE_BASE_TOP - SHELF_BASE_TOP)) + 'px';
  }

  function layoutTree() {
    if (!sidebarRootEl) return;
    var rr = sidebarRootEl.getBoundingClientRect();
    if (!rr.width || !rr.height) return;
    if (rr.width < 150) {
      body.setAttribute('data-dsh-tree', '0');
      return;
    }

    /* 列表里最后一行可见内容的底部 */
    var rows = sidebarRootEl.querySelectorAll('[class*="_sessionRow"], [class*="_projectRow"]');
    var lastBottom = rr.top + 8;
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i].getBoundingClientRect();
      if (r.height <= 0 || r.width <= 0) continue;
      if (r.top > rr.bottom) continue;
      if (r.bottom > lastBottom) lastBottom = r.bottom;
    }

    /* 底部账号/设置行（footArea 或 trigger）的顶部 */
    var foot = sidebarRootEl.querySelector('[class*="_footArea"]') ||
      sidebarRootEl.querySelector('[class*="_trigger"]');
    var footTop = foot ? foot.getBoundingClientRect().top : rr.bottom - 8;
    if (!footTop || footTop > rr.bottom + 40) footTop = rr.bottom - 8;

    var top = Math.max(rr.top + 8, lastBottom + 12);
    var bottom = Math.min(rr.bottom - 6, footTop - 8);
    var avail = bottom - top;

    /* 空间不足就不显示，绝不让植物垫到文字后面 */
    if (avail < 120) {
      body.setAttribute('data-dsh-tree', '0');
      return;
    }
    body.setAttribute('data-dsh-tree', '1');
    var h = Math.min(380, avail);
    var w = h / TREE_RATIO;
    if (w > 236) { w = 236; h = w * TREE_RATIO; }
    tree.style.width = w.toFixed(1) + 'px';
    tree.style.height = h.toFixed(1) + 'px';
    tree.style.bottom = (rr.bottom - bottom).toFixed(1) + 'px';
    tree.style.left = (-w * 0.18).toFixed(1) + 'px';
  }

  /* Keep the floor vignette below the actual composer and inside the center
     panel. If controls occupy that space, omit it rather than cover them. */
  function layoutHome(global) {
    var content = doc.querySelector('[data-conversation-content]');
    var hero = content && content.getAttribute('data-content-phase') === 'hero';
    var card = content && content.querySelector('[data-composer-card]');
    /* The composer seat can be a resident sibling of the content. */
    if (!card && hero) card = doc.querySelector('[data-composer-card]');
    var center = doc.querySelector('[data-dsh-col="center"]');
    var blocked = global || body.getAttribute('data-dsh-modal') === '1' ||
      !!doc.querySelector('[role="dialog"][aria-modal="true"]') || body.hasAttribute('data-ds-dark-theme');
    if (!hero || !card || !center || blocked || !IMG.sleepingDog || !IMG.watchingCat) {
      if (blocked || hero || homePhase !== 'active') homeScene.setAttribute('data-visible', '0');
      return;
    }
    var cr = center.getBoundingClientRect(), r = card.getBoundingClientRect();
    var bottom = Math.min(cr.bottom - 12, window.innerHeight - 12);
    var leftBound = Math.max(cr.left + 12, 0), rightBound = Math.min(cr.right - 12, window.innerWidth);
    var height = bottom - r.bottom - 18;
    var scale = Math.min(1, (rightBound - leftBound) / 750, height / 310);
    if (!r.width || scale < 0.4) { homeScene.setAttribute('data-visible', '0'); return; }
    var top = bottom - 310 * scale;
    homeScene.style.left = leftBound + 'px';
    homeScene.style.top = top + 'px';
    homeScene.style.width = ((rightBound - leftBound) / scale) + 'px';
    homeScene.style.transformOrigin = 'top left';
    homeScene.style.transform = 'scale(' + scale + ')';
    homeScene.setAttribute('data-visible', '1');
    /* Test each vignette independently; empty central space is not an obstacle. */
    var groups = [homeScene.querySelectorAll('.dsh-home-chair, .dsh-home-dog'),
                  homeScene.querySelectorAll('.dsh-home-drawer, .dsh-home-bowl, .dsh-home-cat')];
    var controls = center.querySelectorAll('button, a, input, textarea, select, [role="button"], [role="tab"], [contenteditable="true"]');
    for (var g = 0; g < groups.length; g++) {
      for (var j = 0; j < groups[g].length; j++) groups[g][j].style.visibility = '';
      var overlaps = false;
      for (var i = 0; i < controls.length && !overlaps; i++) {
        var box = controls[i].getBoundingClientRect();
        if (!box.width || !box.height) continue;
        for (var k = 0; k < groups[g].length; k++) {
          var art = groups[g][k].getBoundingClientRect();
          if (box.left < art.right && box.right > art.left && box.top < art.bottom && box.bottom > art.top) { overlaps = true; break; }
        }
      }
      if (overlaps) for (var n = 0; n < groups[g].length; n++) groups[g][n].style.visibility = 'hidden';
    }
  }

  function updateHomePhase() {
    var content = doc.querySelector('[data-conversation-content]');
    var phase = content && content.getAttribute('data-content-phase');
    if (phase === 'hero' && HOME_LOCALE && HOME_LOCALE.en && HOME_LOCALE.zh) {
      var titleGroup = content.querySelector('[class*="_headline"] [class*="_titleGroup"]');
      if (titleGroup) {
        if (!homeGreeting || homeGreeting.parentNode !== titleGroup) {
          if (homeGreeting && homeGreeting.parentNode) {
            homeGreeting.parentNode.removeAttribute('data-dsh-greeting');
            homeGreeting.parentNode.removeChild(homeGreeting);
          }
          homeGreeting = make('div', 'dsh-home-greeting');
          homeGreeting.appendChild(make('div', 'dsh-home-greeting-title'));
          homeGreeting.appendChild(make('div', 'dsh-home-greeting-welcome'));
          homeGreeting.appendChild(make('div', 'dsh-home-greeting-detail'));
          titleGroup.appendChild(homeGreeting);
        }
        if (!titleGroup.hasAttribute('data-dsh-greeting')) titleGroup.setAttribute('data-dsh-greeting', '');
        var language = (doc.documentElement.lang || (navigator.languages && navigator.languages[0]) || navigator.language || 'en').toLowerCase();
        var words = HOME_LOCALE[language.split(/[-_]/)[0]] || HOME_LOCALE.en;
        var hour = new Date().getHours();
        var key = hour < 11 ? 'morning' : hour < 14 && words.noon ? 'noon' : hour < 18 ? 'afternoon' : 'evening';
        var texts = [words[key] || HOME_LOCALE.en[key], words.welcome, words.detail];
        for (var i = 0; i < texts.length; i++) {
          if (homeGreeting.children[i].textContent !== texts[i]) homeGreeting.children[i].textContent = texts[i];
        }
        var greetingLang = words === HOME_LOCALE.zh ? 'zh' : 'en';
        if (homeGreeting.lang !== greetingLang) homeGreeting.lang = greetingLang;
      }
    }
    var card = doc.querySelector('[data-composer-card]');
    var seat = card && card.closest('[data-composer-seat], [class*="_composerSeat"]');
    if (homePhase === 'hero' && phase === 'active' && content === homeContent && seat && seat === homeSeat) {
      var first = homeSeatRect;
      if (homeFade) homeFade.cancel();
      if (homeScene.getAttribute('data-visible') === '1' && homeScene.animate && !prefersReduced()) {
        homeFade = homeScene.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 200, easing: 'ease-out' });
        homeFade.onfinish = function () { homeScene.setAttribute('data-visible', '0'); homeFade = null; };
      } else homeScene.setAttribute('data-visible', '0');
      if (homeRaf) cancelAnimationFrame(homeRaf);
      homeRaf = requestAnimationFrame(function () {
        homeRaf = 0;
        if (!first || !seat.isConnected || prefersReduced() || !seat.animate ||
            window.getComputedStyle(seat).transform !== 'none' ||
            (seat.getAnimations && seat.getAnimations().length)) return;
        var last = seat.getBoundingClientRect();
        var dx = first.left - last.left, dy = first.top - last.top;
        if (!last.width || !last.height || Math.abs(first.width - last.width) > 2 ||
            Math.abs(first.height - last.height) > 2 || Math.abs(dx) > 2 ||
            Math.abs(dy) < 2 || Math.abs(dy) > window.innerHeight * 0.7) return;
        if (homeFlip) homeFlip.cancel();
        homeFlip = seat.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'translateY(0)' }],
          { duration: 220, easing: 'cubic-bezier(.22,1,.36,1)' });
        homeFlip.onfinish = function () { homeFlip = null; };
      });
    } else if (phase !== homePhase || content !== homeContent) {
      if (homeFade) { homeFade.cancel(); homeFade = null; }
      if (homeFlip) { homeFlip.cancel(); homeFlip = null; }
      if (homeRaf) { cancelAnimationFrame(homeRaf); homeRaf = 0; }
      homeScene.setAttribute('data-visible', '0');
    }
    homePhase = phase; homeContent = content; homeSeat = seat;
    if (phase === 'hero' && seat) homeSeatRect = seat.getBoundingClientRect();
    else if (phase !== 'hero') homeSeatRect = null;
  }

  /* ---------- 主循环 ---------- */
  var ro = null;
  var roCard = null;
  var followRaf = 0;
  var followFrames = 0;

  function watchCardResize() {
    if (!ro) return;
    var card = doc.querySelector('[data-composer-card]');
    if (!card) return;
    if (roCard === card) return;
    try { ro.disconnect(); ro.observe(card); } catch (err) { /* ignore */ }
    roCard = card;
  }

  function tick() {
    if (!body || !doc.documentElement.contains(body)) return;
    tagDom();
    if (!frameEl || !mainEl) return;
    watchCardResize();
    var global = applyMode();
    updateHomePhase();
    layoutHome(global);
    layoutFrameLines();
    clipPets();
    layoutStage();
    layoutPets(global);
    layoutTree();
  }

  /* 输入框撑高/收起时连续跟随几帧，保证猫的底边始终贴住顶边 */
  function followStep() {
    followRaf = 0;
    tick();
    if (followFrames-- > 0) followRaf = requestAnimationFrame(followStep);
  }
  function startFollow(frames) {
    followFrames = frames || 20;
    if (!followRaf) followRaf = requestAnimationFrame(followStep);
  }

  tick();
  var homeObserver = new MutationObserver(function () {
    updateHomePhase();
    layoutHome(body.getAttribute('data-dsh-global') === '1');
  });
  homeObserver.observe(body, { subtree: true, childList: true, attributes: true, attributeFilter: ['data-content-phase'] });
  var timer = setInterval(tick, 350);

  /* 尺寸 / 路由变化提前响应 */
  function onResize() {
    if (typeof lastGlobal !== 'undefined') lastGlobal = null;
    tick();
    startFollow(24); /* ~400ms：覆盖输入框展开/收起的过渡 */
  }
  window.addEventListener('resize', onResize);

  if (window.ResizeObserver) {
    try {
      ro = new ResizeObserver(onResize);
      watchCardResize();
    } catch (err) { /* ignore */ }
  }

  /* ---------- 清理 ---------- */
  return function dispose() {
    clearInterval(timer);
    homeObserver.disconnect();
    if (homeRaf) cancelAnimationFrame(homeRaf);
    if (homeFade) homeFade.cancel();
    if (homeFlip) homeFlip.cancel();
    if (followRaf) { cancelAnimationFrame(followRaf); followRaf = 0; }
    window.removeEventListener('resize', onResize);
    doc.removeEventListener('pointerdown', lightOutside, true);
    doc.removeEventListener('keydown', lightKey, true);
    if (ro) {
      try { ro.disconnect(); } catch (err) { /* ignore */ }
    }
    clearCatTimer();
    removeGhosts();
    if (homeGreeting && homeGreeting.parentNode) {
      homeGreeting.parentNode.removeAttribute('data-dsh-greeting');
      homeGreeting.parentNode.removeChild(homeGreeting);
    }
    var nodes = [marker, frameLines, pets, homeScene, tree, stage, catTip, lightUI];
    for (var i = 0; i < nodes.length; i++) {
      if (nodes[i] && nodes[i].parentNode) nodes[i].parentNode.removeChild(nodes[i]);
    }
    if (styleNode && styleNode.parentNode) styleNode.parentNode.removeChild(styleNode);
  };
}

    return {
      apply(ctx) {
        const dispose = mountScene(CSS, IMG, HOME_LOCALE);
        if (dispose) ctx.effect(() => dispose);
      },
    };
  },
});
